const syncCompanyLockedAdminControls = () => {
    const companyAllowed = window.AppSession?.getCompanyAllowedPages?.() || {};

    // 1. Dashboard Quick Action: Configure Fees (Collection)
    const collQuickBtn = document.getElementById('admin-quick-action-collection');
    const collQuickBadge = document.getElementById('admin-quick-action-collection-badge');
    const isCollectionLocked = companyAllowed.collection === false;
    if (collQuickBtn) {
        collQuickBtn.classList.toggle('border-amber-200', isCollectionLocked);
        collQuickBtn.classList.toggle('bg-amber-50/35', isCollectionLocked);
        collQuickBtn.dataset.companyLocked = isCollectionLocked ? 'true' : 'false';
    }
    if (collQuickBadge) {
        collQuickBadge.classList.toggle('hidden', !isCollectionLocked);
    }

    // 2. Add Staff & Edit Staff permission checkboxes
    ['st', 'e-st'].forEach((prefix) => {
        STAFF_PERM_COMPANY_MAP.forEach(({ suffix, moduleKey, label }) => {
            const cb = document.getElementById(`${prefix}-${suffix}`);
            const row = cb?.closest('label');
            if (!cb || !row) return;
            const locked = companyAllowed[moduleKey] === false;
            cb.disabled = locked;
            row.dataset.companyLockedModule = locked ? moduleKey : '';
            row.dataset.companyLockedLabel = locked ? label : '';
            row.classList.toggle('bg-amber-50/40', locked);
            row.classList.toggle('border-amber-200', locked);
            row.classList.toggle('bg-white', !locked);
            row.classList.toggle('border-gray-200', !locked);

            const infoCol = row.querySelector('div');
            let badgeEl = row.querySelector('.company-perm-premium-badge');
            if (locked) {
                if (!badgeEl && infoCol) {
                    badgeEl = document.createElement('span');
                    badgeEl.className = 'company-perm-premium-badge inline-flex items-center gap-1 mt-1.5 px-2 py-0.5 rounded-full text-[10px] font-black uppercase tracking-wider bg-amber-100 text-amber-800 border border-amber-300';
                    badgeEl.innerHTML = '<i class="fas fa-crown text-[8px]"></i><span>Premium - Upgrade</span>';
                    infoCol.appendChild(badgeEl);
                }
            } else if (badgeEl) {
                badgeEl.remove();
            }

            if (!row.dataset.premiumClickBound) {
                row.dataset.premiumClickBound = '1';
                row.addEventListener('click', (ev) => {
                    const lockedKey = row.dataset.companyLockedModule;
                    if (!lockedKey) return;
                    ev.preventDefault();
                    ev.stopPropagation();
                    openAdminPremiumUpgradeModal(lockedKey, row.dataset.companyLockedLabel || '');
                });
            }
        });
    });

    // 3. Basic (Free) Plan PRO Feature Locks across Admin Sidebar & Action Buttons
    const adminProBindings = [
        ['a.nav-link[href="#manage-alumni"]', 'alumniManagement', 'Alumni Management'],
        ['a.nav-link[href="#student-continuity"]', 'studentContinuity', 'Discontinue & Re-admission'],
        ['a.nav-link[href="#batch-promotion"]', 'batchPromotion', 'Class Promotion'],
        ['a.nav-link[href="#workflow-modules"]', 'workflowOverrides', 'Workflow & Module Overrides'],
        ['.admin-quick-action[data-target-page="batch-promotion"]', 'batchPromotion', 'Class Promotion'],
        ['.admin-quick-action[data-target-page="workflow-modules"]', 'workflowOverrides', 'Workflow & Module Overrides'],
        ['#excel-drop-zone', 'excelBulkImport', 'Bulk Excel Student Import'],
        ['#export-students-excel-btn', 'excelExport', 'Student Excel Export'],
        ['#export-students-pdf-btn', 'excelExport', 'Student PDF Export'],
        ['#export-alumni-excel-btn', 'excelExport', 'Alumni Excel Export'],
        ['#export-alumni-pdf-btn', 'excelExport', 'Alumni PDF Export'],
        ['#open-student-fields-config-btn', 'customStudentFields', 'Custom Student Fields'],
        ['#dir-cat-add-btn', 'customDirectoryCategories', 'Custom Staff & Directory Categories'],
        ['#backup-export-btn', 'backupAndAudit', 'Data Backup & Restore'],
        ['#btn-run-data-health-check', 'multiAcademicYears', 'Multi-Year Data Integrity Validator'],
        ['#create-group-btn', 'studentGroups', 'Student Sibling Groups'],
        ['#result-download-template-btn', 'blankSheets', 'Blank Excel Templates']
    ];
    adminProBindings.forEach(([selector, featureKey, featureName]) => {
        const el = document.querySelector(selector);
        if (el) {
            decorateProLockElement(el, {
                featureKey,
                featureName,
                institutionName: latestConfigData?.institutionName || ''
            });
        }
    });
    if (typeof updateGalleryLimitUI === 'function') {
        try { updateGalleryLimitUI(); } catch (_) {}
    }
};

const renderWorkflowModules = async () => {
    let currentConfig = getEnabledModulesConfig();
    try {
        const snap = await getDoc(getConfigRef());
        if (snap.exists()) {
            const data = snap.data();
            if (data?.enabledModules && typeof data.enabledModules === 'object') {
                currentConfig = { ...DEFAULT_ENABLED_MODULES, ...data.enabledModules };
                localStorage.setItem('app_enabled_modules', JSON.stringify(currentConfig));
            }
        }
    } catch (err) {
        console.warn('Could not fetch remote module settings, using local:', err);
    }

    const companyAllowed = window.AppSession?.getCompanyAllowedPages?.() || {};
    Object.keys(DEFAULT_ENABLED_MODULES).forEach((key) => {
        const card = document.querySelector(`[data-module-card="${key}"]`);
        const toggle = document.getElementById(`module-toggle-${key}`);
        const allowedByCompany = companyAllowed[key] !== false;
        const isEnabled = allowedByCompany && (currentConfig[key] !== false);
        if (toggle) {
            toggle.checked = isEnabled;
            toggle.disabled = !allowedByCompany;
            toggle.title = allowedByCompany ? '' : 'Premium feature - Upgrade your plan to unlock';
        }
        updateWorkflowModuleBadgeUI(key, isEnabled);
        if (card) {
            card.dataset.companyLocked = allowedByCompany ? 'false' : 'true';
            card.classList.toggle('border-amber-200', !allowedByCompany);
            card.classList.toggle('bg-amber-50/25', !allowedByCompany);
            card.classList.toggle('cursor-pointer', !allowedByCompany);
            if (!card.dataset.premiumBound) {
                card.dataset.premiumBound = '1';
                card.addEventListener('click', (ev) => {
                    if (card.dataset.companyLocked !== 'true') return;
                    ev.preventDefault();
                    ev.stopPropagation();
                    openAdminPremiumUpgradeModal(key, WORKFLOW_MODULE_LABELS[key] || '');
                });
            }
        }
        if (!allowedByCompany) {
            const badge = document.getElementById(`module-badge-${key}`);
            if (badge) {
                badge.innerHTML = '<i class="fas fa-crown text-[9px]"></i><span>Premium - Upgrade</span>';
                badge.className = 'inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase tracking-wider bg-amber-100 text-amber-800 border border-amber-300 cursor-pointer whitespace-nowrap';
            }
        }
    });
    syncCompanyLockedAdminControls();
};

const saveWorkflowModules = async () => {
    if (!requirePermission('academic-years.manage')) return;

    const saveBtn = document.getElementById('btn-save-workflow-modules');
    const originalHtml = saveBtn ? saveBtn.innerHTML : '';
    if (saveBtn) {
        saveBtn.disabled = true;
        saveBtn.innerHTML = '<i class="fas fa-spinner fa-spin mr-2"></i> Saving...';
    }

    try {
        const companyAllowed = window.AppSession?.getCompanyAllowedPages?.() || {};
        const enabledModules = {};
        Object.keys(DEFAULT_ENABLED_MODULES).forEach((key) => {
            const toggle = document.getElementById(`module-toggle-${key}`);
            enabledModules[key] = companyAllowed[key] === false ? false : (toggle ? Boolean(toggle.checked) : true);
        });

        // 1. Persist directly to Firestore config document (with merge: true so no other settings are touched)
        await setDoc(getConfigRef(), { enabledModules }, { merge: true });

        // 2. Cache in localStorage for immediate synchronous guards on page loads
        localStorage.setItem('app_enabled_modules', JSON.stringify(enabledModules));

        // 3. Log audit event
        await logAuditEvent({
            category: 'settings',
            action: 'workflow_modules.update',
            entityType: 'config',
            entityId: 'enabledModules',
            message: `Institutional workflow modules updated: ${Object.entries(enabledModules).map(([k, v]) => `${k}:${v ? 'ON' : 'OFF'}`).join(', ')}`
        });

        alert('Workflow & Module settings saved successfully!\n\nDisabled modules will be hidden from staff navigation and restricted from direct access.');
    } catch (error) {
        console.error('Failed to save workflow modules:', error);
        alert('Failed to save module settings: ' + (error.message || error));
    } finally {
        if (saveBtn) {
            saveBtn.disabled = false;
            saveBtn.innerHTML = originalHtml;
        }
    }
};

// --- STUDENT PORTAL CONFIGURATION ---
const DEFAULT_STUDENT_PORTAL_CONFIG = {
    tabs: {
        profile: true,
        fees: true,
        attendance: true,
        timetable: true,
        syllabus: true,
        results: true,
        activities: true,
        publicHome: true
    },
    order: ['profile', 'fees', 'attendance', 'timetable', 'syllabus', 'results', 'activities', 'publicHome']
};

let cachedStudentPortalConfig = { ...DEFAULT_STUDENT_PORTAL_CONFIG };
let stuPortalSortableInitialized = false;

const initStudentPortalSortable = () => {
    const container = document.getElementById('stu-portal-tabs-sortable-list');
    if (!container || stuPortalSortableInitialized) return;
    stuPortalSortableInitialized = true;

    let draggedItem = null;

    container.addEventListener('dragstart', (e) => {
        const row = e.target.closest('.stu-portal-sortable-row');
        if (!row) return;
        draggedItem = row;
        row.classList.add('opacity-40', 'border-blue-500', 'bg-blue-50/50');
        if (e.dataTransfer) {
            e.dataTransfer.effectAllowed = 'move';
            e.dataTransfer.setData('text/plain', row.dataset.tabKey || '');
        }
    });

    container.addEventListener('dragend', (e) => {
        const row = e.target.closest('.stu-portal-sortable-row');
        if (row) {
            row.classList.remove('opacity-40', 'border-blue-500', 'bg-blue-50/50');
        }
        draggedItem = null;
    });

    container.addEventListener('dragover', (e) => {
        e.preventDefault();
        if (e.dataTransfer) e.dataTransfer.dropEffect = 'move';
        const targetRow = e.target.closest('.stu-portal-sortable-row');
        if (!targetRow || !draggedItem || targetRow === draggedItem) return;

        const bounding = targetRow.getBoundingClientRect();
        const offset = e.clientY - bounding.top;
        if (offset > bounding.height / 2) {
            targetRow.after(draggedItem);
        } else {
            targetRow.before(draggedItem);
        }
    });

    container.addEventListener('drop', (e) => {
        e.preventDefault();
        if (draggedItem) {
            draggedItem.classList.remove('opacity-40', 'border-blue-500', 'bg-blue-50/50');
            draggedItem = null;
        }
    });

    // Up and Down button controls
    container.addEventListener('click', (e) => {
        const upBtn = e.target.closest('.btn-move-tab-up');
        const downBtn = e.target.closest('.btn-move-tab-down');
        if (upBtn) {
            const row = upBtn.closest('.stu-portal-sortable-row');
            if (row && row.previousElementSibling) {
                container.insertBefore(row, row.previousElementSibling);
            }
        } else if (downBtn) {
            const row = downBtn.closest('.stu-portal-sortable-row');
            if (row && row.nextElementSibling) {
                row.nextElementSibling.after(row);
            }
        }
    });
};

const openStudentPortalConfigModal = async () => {
    if (window.AppSession?.isCompanyPageAllowed?.('student') === false) {
        openAdminPremiumUpgradeModal('student', WORKFLOW_MODULE_LABELS.student);
        return;
    }
    const modal = document.getElementById('modal-student-portal-config');
    if (!modal) return;

    try {
        const snap = await getDoc(getConfigRef());
        if (snap.exists()) {
            const data = snap.data();
            if (data?.studentPortalConfig && typeof data.studentPortalConfig === 'object') {
                const loadedTabs = { ...DEFAULT_STUDENT_PORTAL_CONFIG.tabs, ...(data.studentPortalConfig.tabs || {}) };
                let loadedOrder = Array.isArray(data.studentPortalConfig.order) ? [...data.studentPortalConfig.order] : [];
                DEFAULT_STUDENT_PORTAL_CONFIG.order.forEach((k) => {
                    if (!loadedOrder.includes(k)) loadedOrder.push(k);
                });
                loadedOrder = loadedOrder.filter((k) => k in DEFAULT_STUDENT_PORTAL_CONFIG.tabs);
                cachedStudentPortalConfig = {
                    tabs: loadedTabs,
                    order: loadedOrder
                };
            }
        }
    } catch (e) {
        console.warn('Could not fetch student portal config:', e);
    }

    initStudentPortalSortable();

    const tabs = cachedStudentPortalConfig.tabs || DEFAULT_STUDENT_PORTAL_CONFIG.tabs;
    const order = cachedStudentPortalConfig.order || DEFAULT_STUDENT_PORTAL_CONFIG.order;

    // Arrange rows according to order
    const listEl = document.getElementById('stu-portal-tabs-sortable-list');
    if (listEl) {
        order.forEach((tabKey) => {
            const row = listEl.querySelector(`[data-tab-key="${tabKey}"]`);
            if (row) listEl.appendChild(row);
        });
    }

    const feeToggle = document.getElementById('cfg-stu-tab-fees');
    const attToggle = document.getElementById('cfg-stu-tab-attendance');
    const ttToggle = document.getElementById('cfg-stu-tab-timetable');
    const sylToggle = document.getElementById('cfg-stu-tab-syllabus');
    const resToggle = document.getElementById('cfg-stu-tab-results');
    const actToggle = document.getElementById('cfg-stu-tab-activities');
    const pubToggle = document.getElementById('cfg-stu-tab-publicHome');

    if (feeToggle) feeToggle.checked = tabs.fees !== false;
    if (attToggle) attToggle.checked = tabs.attendance !== false;
    if (ttToggle) ttToggle.checked = tabs.timetable !== false;
    if (sylToggle) sylToggle.checked = tabs.syllabus !== false;
    if (resToggle) resToggle.checked = tabs.results !== false;
    if (actToggle) actToggle.checked = tabs.activities !== false;
    if (pubToggle) pubToggle.checked = tabs.publicHome !== false;

    modal.classList.remove('hidden');
    modal.classList.add('flex');
};

const closeStudentPortalConfigModal = () => {
    const modal = document.getElementById('modal-student-portal-config');
    if (!modal) return;
    modal.classList.add('hidden');
    modal.classList.remove('flex');
};

const saveStudentPortalConfig = async () => {
    if (!requirePermission('academic-years.manage')) return;

    const saveBtn = document.getElementById('btn-save-student-portal-config');
    const originalHtml = saveBtn ? saveBtn.innerHTML : '';
    if (saveBtn) {
        saveBtn.disabled = true;
        saveBtn.innerHTML = '<i class="fas fa-spinner fa-spin mr-2"></i> Saving...';
    }

    try {
        const listEl = document.getElementById('stu-portal-tabs-sortable-list');
        const rows = listEl ? Array.from(listEl.querySelectorAll('.stu-portal-sortable-row')) : [];
        const currentOrder = rows.map((r) => r.dataset.tabKey).filter(Boolean);

        const finalOrder = currentOrder.length ? currentOrder : [...DEFAULT_STUDENT_PORTAL_CONFIG.order];
        DEFAULT_STUDENT_PORTAL_CONFIG.order.forEach((k) => {
            if (!finalOrder.includes(k)) finalOrder.push(k);
        });

        const studentPortalConfig = {
            tabs: {
                profile: true,
                fees: Boolean(document.getElementById('cfg-stu-tab-fees')?.checked),
                attendance: Boolean(document.getElementById('cfg-stu-tab-attendance')?.checked),
                timetable: Boolean(document.getElementById('cfg-stu-tab-timetable')?.checked),
                syllabus: Boolean(document.getElementById('cfg-stu-tab-syllabus')?.checked),
                results: Boolean(document.getElementById('cfg-stu-tab-results')?.checked),
                activities: Boolean(document.getElementById('cfg-stu-tab-activities')?.checked),
                publicHome: Boolean(document.getElementById('cfg-stu-tab-publicHome')?.checked)
            },
            order: finalOrder
        };

        await setDoc(getConfigRef(), { studentPortalConfig }, { merge: true });
        cachedStudentPortalConfig = studentPortalConfig;
        localStorage.setItem('app_student_portal_config', JSON.stringify(studentPortalConfig));

        await logAuditEvent({
            category: 'settings',
            action: 'student_portal_config.update',
            entityType: 'config',
            entityId: 'studentPortalConfig',
            message: `Updated student portal tab configuration: ${Object.entries(studentPortalConfig.tabs).map(([k, v]) => `${k}:${v ? 'ON' : 'OFF'}`).join(', ')} | Order: ${finalOrder.join(' > ')}`
        });

        closeStudentPortalConfigModal();
        alert('Student Portal configuration saved successfully!\n\nChanges will immediately reflect in the Student Portal navigation.');
    } catch (error) {
        console.error('Failed to save student portal config:', error);
        alert('Failed to save config: ' + (error.message || error));
    } finally {
        if (saveBtn) {
            saveBtn.disabled = false;
            saveBtn.innerHTML = originalHtml;
        }
    }
};

const renderAcademicYears = () => {
    const listEl = document.getElementById('academic-years-list');
    if (academicYears.length === 0) {
        listEl.innerHTML = '<div class="text-center py-8 bg-gray-50 rounded-xl border border-dashed text-gray-500 font-medium">No academic years configured yet.</div>';
        return;
    }

    listEl.innerHTML = [...academicYears]
        .sort((a, b) => compareAcademicYearLabels(b.label || '', a.label || ''))
        .map((year) => {
            const isCurrent = year.label === activeAcademicYear;
            const isArchived = !isCurrent && year.status === 'archived';
            const currentStatus = isCurrent ? 'current' : (isArchived ? 'archived' : 'active');

            const startMonthLabel = MONTH_LABELS[Number(year.startMonth ?? 5)] || MONTH_LABELS[5];
            const endMonthLabel = MONTH_LABELS[Number(year.endMonth ?? 4)] || MONTH_LABELS[4];

            // Counts for this academic year: active studying students (excluding Alumni & Discontinued, matching Publish to Website)
            const totalStudentsCount = getStudyingStudentsForYear(year.label).length;

            const yearClasses = ((Array.isArray(year.classes) && year.classes.length)
                ? year.classes
                : (year.label === activeAcademicYear ? classes : [])
            ).filter((cls) => {
                const upper = String(cls || '').trim().toUpperCase();
                return upper && upper !== 'ALUMNI' && upper !== 'GRADUATED';
            });
            const totalClassesCount = yearClasses.length;

            const totalStaffCount = (allStaff || []).length;

            let badgeHtml = '';
            if (isCurrent) {
                badgeHtml = '<span class="px-2.5 py-1 rounded-full text-xs font-bold bg-emerald-100 text-emerald-800 border border-emerald-200 inline-flex items-center gap-1.5"><i class="fas fa-check-circle text-emerald-600"></i> Current Academic Year</span>';
            } else if (isArchived) {
                badgeHtml = '<span class="px-2.5 py-1 rounded-full text-xs font-bold bg-amber-100 text-amber-800 border border-amber-200">Archive</span>';
            } else {
                badgeHtml = '<span class="px-2.5 py-1 rounded-full text-xs font-bold bg-blue-100 text-blue-800 border border-blue-200">Active</span>';
            }

            return `
                <div class="flex flex-col justify-between bg-white border border-gray-200 rounded-xl p-4 shadow-sm hover:border-gray-300 transition" data-card-year="${escapeHtml(year.label)}">
                    <!-- Top row: Heading (Year) and 3-dot menu button at top-right corner -->
                    <div class="flex items-center justify-between gap-2 border-b border-gray-100 pb-2.5">
                        <div class="flex items-center gap-2">
                            <i class="fas fa-calendar-alt text-blue-600"></i>
                            <span class="text-lg font-extrabold text-gray-900">${escapeHtml(year.label)}</span>
                        </div>
                        <div class="relative">
                            <button class="year-menu-toggle w-8 h-8 rounded-lg border border-gray-200 bg-white hover:bg-gray-50 text-gray-600 flex items-center justify-center transition" data-label="${escapeHtml(year.label)}" title="More actions" aria-label="More actions">
                                <i class="fas fa-ellipsis-v"></i>
                            </button>
                            <div class="year-menu hidden absolute right-0 mt-1 w-44 bg-white border border-gray-200 rounded-lg shadow-lg z-20 overflow-hidden">
                                <button class="year-edit-btn w-full text-left px-3.5 py-2 text-xs font-semibold text-gray-700 hover:bg-blue-50 flex items-center gap-2" data-label="${escapeHtml(year.label)}"><i class="fas fa-edit text-blue-600"></i> Edit months</button>
                                <button class="year-delete-btn w-full text-left px-3.5 py-2 text-xs font-semibold text-red-700 hover:bg-red-50 flex items-center gap-2 border-t border-gray-100" data-label="${escapeHtml(year.label)}"><i class="fas fa-trash text-red-600"></i> Delete year</button>
                            </div>
                        </div>
                    </div>

                    <!-- Second row: Status badge on left, Status dropdown select & Save on right -->
                    <div class="flex items-center justify-between gap-2 mt-3 flex-wrap">
                        <div>
                            ${badgeHtml}
                        </div>
                        <div class="flex items-center gap-1.5">
                            <select class="year-status-select px-2.5 py-1.5 border border-gray-300 rounded-lg text-xs font-bold bg-white text-gray-800 focus:border-blue-500 outline-none transition" data-label="${escapeHtml(year.label)}" data-initial-status="${currentStatus}">
                                <option value="current" ${currentStatus === 'current' ? 'selected' : ''}>Current Academic Year</option>
                                <option value="active" ${currentStatus === 'active' ? 'selected' : ''}>Active</option>
                                <option value="archived" ${currentStatus === 'archived' ? 'selected' : ''}>Archive</option>
                            </select>
                            <button type="button" class="save-year-status-btn hidden px-2.5 py-1.5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-xs font-bold shadow-xs transition items-center gap-1" data-label="${escapeHtml(year.label)}">
                                <i class="fas fa-save"></i> <span>Save</span>
                            </button>
                        </div>
                    </div>

                    <!-- Month Span: only month to month under status -->
                    <div class="text-xs font-semibold text-gray-600 mt-2.5 bg-slate-50 border border-slate-100 px-3 py-1.5 rounded-lg flex items-center gap-1.5">
                        <i class="fas fa-clock text-blue-500 text-xs"></i>
                        <span>Months: <strong class="text-gray-800">${startMonthLabel}</strong> → <strong class="text-gray-800">${endMonthLabel}</strong></span>
                    </div>

                    <!-- Academic Year Counters: Total Students, Total Classes, Total Staff -->
                    <div class="grid grid-cols-3 gap-2 pt-3 mt-3 border-t border-gray-100 text-center">
                        <div class="bg-blue-50/80 border border-blue-100 rounded-lg p-2">
                            <div class="text-[10px] font-bold text-blue-700 uppercase tracking-wider">Students</div>
                            <div class="text-base font-extrabold text-blue-900 mt-0.5">${totalStudentsCount}</div>
                        </div>
                        <div class="bg-indigo-50/80 border border-indigo-100 rounded-lg p-2">
                            <div class="text-[10px] font-bold text-indigo-700 uppercase tracking-wider">Classes</div>
                            <div class="text-base font-extrabold text-indigo-900 mt-0.5">${totalClassesCount}</div>
                        </div>
                        <div class="bg-emerald-50/80 border border-emerald-100 rounded-lg p-2">
                            <div class="text-[10px] font-bold text-emerald-700 uppercase tracking-wider">Staff</div>
                            <div class="text-base font-extrabold text-emerald-900 mt-0.5">${totalStaffCount}</div>
                        </div>
                    </div>
                </div>`;
        }).join('');
};

// --- MULTI-YEAR DATA INTEGRITY & LONGITUDINAL HEALTH VALIDATOR ---
let healthScanResults = {
    totalStudents: 0,
    healthyStudents: 0,
    needsBackfillStudents: [],
    unlinkedPayments: [],
    unlinkedGroups: []
};

const scanMultiYearDataHealth = () => {
    const totalStudents = (rawStudents || []).length;
    const needsBackfill = [];
    let healthyCount = 0;

    (rawStudents || []).forEach((st) => {
        const studentYear = st.academicYear || activeAcademicYear || currentAcademicYear;
        const yearsMap = (st.academicYears && typeof st.academicYears === 'object') ? st.academicYears : null;

        if (yearsMap && Object.keys(yearsMap).length > 0 && yearsMap[studentYear]) {
            healthyCount++;
        } else {
            needsBackfill.push(st);
        }
    });

    const unlinkedPayments = (allPayments || []).filter((p) => !p.academicYear);
    const unlinkedGroups = (allStudentGroups || []).filter((g) => !g.academicYear);

    healthScanResults = {
        totalStudents,
        healthyStudents: healthyCount,
        needsBackfillStudents: needsBackfill,
        unlinkedPayments,
        unlinkedGroups
    };

    const container = document.getElementById('data-health-results-container');
    if (container) container.classList.remove('hidden');

    const totalEl = document.getElementById('health-metric-total-students');
    const healthyEl = document.getElementById('health-metric-healthy-students');
    const backfillEl = document.getElementById('health-metric-needs-backfill');
    const unlinkedEl = document.getElementById('health-metric-unlinked-receipts');
    const summaryText = document.getElementById('health-summary-text');
    const repairBtn = document.getElementById('btn-apply-health-repairs');
    const logBox = document.getElementById('health-log-box');

    if (totalEl) totalEl.textContent = totalStudents;
    if (healthyEl) healthyEl.textContent = healthyCount;
    if (backfillEl) backfillEl.textContent = needsBackfill.length;
    if (unlinkedEl) unlinkedEl.textContent = unlinkedPayments.length;

    const totalIssues = needsBackfill.length + unlinkedPayments.length + unlinkedGroups.length;

    if (totalIssues === 0) {
        if (summaryText) summaryText.innerHTML = '<span class="text-emerald-700 font-bold"><i class="fas fa-check-circle mr-1"></i>All institutional records are 100% healthy and verified across all sessions!</span>';
        if (repairBtn) {
            repairBtn.disabled = true;
            repairBtn.classList.add('opacity-50', 'cursor-not-allowed');
        }
        if (logBox) {
            logBox.innerHTML = `
                <div>[${new Date().toLocaleTimeString()}] Audit complete. Evaluated ${totalStudents} students, ${(allPayments || []).length} payment receipts, and ${(allStudentGroups || []).length} groups.</div>
                <div class="text-emerald-400 font-bold">[${new Date().toLocaleTimeString()}] PASS: Zero unlinked records or orphaned session documents detected.</div>
            `;
        }
    } else {
        if (summaryText) summaryText.innerHTML = `<span class="text-amber-700 font-bold"><i class="fas fa-exclamation-triangle mr-1"></i>Found ${needsBackfill.length} student(s) needing longitudinal maps and ${unlinkedPayments.length} legacy receipt(s) needing session linking.</span>`;
        if (repairBtn) {
            repairBtn.disabled = false;
            repairBtn.classList.remove('opacity-50', 'cursor-not-allowed');
        }
        if (logBox) {
            logBox.innerHTML = `
                <div>[${new Date().toLocaleTimeString()}] Audit scan started...</div>
                <div>[${new Date().toLocaleTimeString()}] Total Students: ${totalStudents} (Healthy: ${healthyCount}, Missing Year Maps: ${needsBackfill.length})</div>
                <div>[${new Date().toLocaleTimeString()}] Payments: ${unlinkedPayments.length} legacy receipts missing explicit academicYear tag.</div>
                <div>[${new Date().toLocaleTimeString()}] Groups: ${unlinkedGroups.length} legacy groups missing academicYear tag.</div>
                <div class="text-amber-400 font-bold">[${new Date().toLocaleTimeString()}] Ready to apply automated backfills. Click 'Apply Automatic Backfills & Repairs'.</div>
            `;
        }
    }
};

const applyMultiYearDataRepairs = async () => {
    if (!requirePermission('academic-years.manage')) return;

    const { needsBackfillStudents, unlinkedPayments, unlinkedGroups } = healthScanResults;
    const totalIssues = (needsBackfillStudents?.length || 0) + (unlinkedPayments?.length || 0) + (unlinkedGroups?.length || 0);
    if (totalIssues === 0) return alert('All records are already 100% healthy.');

    if (!confirm(`Apply automated multi-year data repairs for ${totalIssues} record(s)?\n\n• ${needsBackfillStudents.length} Students: Backfill longitudinal academicYears map\n• ${unlinkedPayments.length} Payments: Stamp academicYear from transaction dates\n• ${unlinkedGroups.length} Groups: Link to active/current session\n\nExisting values will be preserved. Proceed?`)) return;

    const repairBtn = document.getElementById('btn-apply-health-repairs');
    const pContainer = document.getElementById('health-progress-bar-container');
    const pBar = document.getElementById('health-progress-bar');
    const pLabel = document.getElementById('health-progress-label');
    const logBox = document.getElementById('health-log-box');

    if (repairBtn) {
        repairBtn.disabled = true;
        repairBtn.classList.add('opacity-50');
    }
    if (pContainer) pContainer.classList.remove('hidden');

    const appendLog = (msg, isSuccess = false) => {
        if (!logBox) return;
        const div = document.createElement('div');
        if (isSuccess) div.className = 'text-emerald-400 font-bold';
        div.textContent = `[${new Date().toLocaleTimeString()}] ${msg}`;
        logBox.appendChild(div);
        logBox.scrollTop = logBox.scrollHeight;
    };

    try {
        appendLog(`Starting automated repair across ${totalIssues} records...`);
        let processed = 0;
        const nowIso = new Date().toISOString();

        // 1. Repair students
        if (needsBackfillStudents && needsBackfillStudents.length) {
            appendLog(`Processing ${needsBackfillStudents.length} student records...`);
            const CHUNK_SIZE = 40;
            for (let i = 0; i < needsBackfillStudents.length; i += CHUNK_SIZE) {
                const chunk = needsBackfillStudents.slice(i, i + CHUNK_SIZE);
                const batch = writeBatch(db);

                chunk.forEach((st) => {
                    const studentYear = st.academicYear || activeAcademicYear || currentAcademicYear;
                    const existingMap = (st.academicYears && typeof st.academicYears === 'object') ? { ...st.academicYears } : {};
                    if (!existingMap[studentYear]) {
                        existingMap[studentYear] = {
                            class: st.class || st.studentClass || 'Unassigned',
                            status: st.status || 'Active',
                            updatedAt: nowIso
                        };
                    }
                    const stRef = doc(db, `${BASE_PATH}/students`, st.id);
                    batch.update(stRef, {
                        academicYears: existingMap,
                        academicYear: studentYear,
                        updatedAt: nowIso
                    });
                });

                await batch.commit();
                processed += chunk.length;
                const pct = Math.round((processed / totalIssues) * 100);
                if (pBar) pBar.style.width = `${pct}%`;
                if (pLabel) pLabel.textContent = `Repaired ${processed} of ${totalIssues} records (${pct}%)...`;
            }
            appendLog(`Successfully backfilled ${needsBackfillStudents.length} student longitudinal maps!`);
        }

        // 2. Repair payments
        if (unlinkedPayments && unlinkedPayments.length) {
            appendLog(`Linking ${unlinkedPayments.length} legacy receipts...`);
            const CHUNK_SIZE = 40;
            for (let i = 0; i < unlinkedPayments.length; i += CHUNK_SIZE) {
                const chunk = unlinkedPayments.slice(i, i + CHUNK_SIZE);
                const batch = writeBatch(db);

                chunk.forEach((p) => {
                    const d = p.timestamp ? new Date(p.timestamp) : (p.dateStr ? new Date(p.dateStr) : new Date());
                    const y = !isNaN(d.getTime()) ? d.getFullYear() : new Date().getFullYear();
                    const m = !isNaN(d.getTime()) ? d.getMonth() : 5;
                    const startY = (m >= 4) ? y : y - 1;
                    const derivedYear = `${startY}-${startY + 1}`;

                    const pRef = doc(db, `${BASE_PATH}/payments`, p.id);
                    batch.update(pRef, {
                        academicYear: derivedYear,
                        updatedAt: Date.now()
                    });
                });

                await batch.commit();
                processed += chunk.length;
                const pct = Math.round((processed / totalIssues) * 100);
                if (pBar) pBar.style.width = `${pct}%`;
                if (pLabel) pLabel.textContent = `Repaired ${processed} of ${totalIssues} records (${pct}%)...`;
            }
            appendLog(`Successfully linked ${unlinkedPayments.length} legacy receipts!`);
        }

        // 3. Repair groups
        if (unlinkedGroups && unlinkedGroups.length) {
            appendLog(`Linking ${unlinkedGroups.length} legacy student groups...`);
            const batch = writeBatch(db);
            unlinkedGroups.forEach((g) => {
                const gRef = doc(db, `${BASE_PATH}/studentGroups`, g.id);
                batch.update(gRef, {
                    academicYear: activeAcademicYear || currentAcademicYear,
                    updatedAt: Date.now()
                });
            });
            await batch.commit();
            appendLog(`Successfully linked ${unlinkedGroups.length} groups!`);
        }

        appendLog('All repairs committed to Firebase successfully!', true);
        if (pBar) pBar.style.width = '100%';
        if (pLabel) pLabel.textContent = '100% Complete - Health Verified!';

        await logAuditEvent({
            category: 'security',
            action: 'data_integrity.repair',
            message: `Applied multi-year automated data backfills across ${totalIssues} records.`
        });

        showToast('Multi-year data integrity successfully backfilled and verified!', 'success');
        setTimeout(() => {
            scanMultiYearDataHealth();
        }, 1500);
    } catch (err) {
        console.error('Data health repair failed:', err);
        appendLog(`ERROR during repair: ${err.message}`);
        alert('Failed to complete automated repairs: ' + err.message);
    } finally {
        if (repairBtn) repairBtn.disabled = false;
    }
};

document.getElementById('btn-run-data-health-check')?.addEventListener('click', scanMultiYearDataHealth);
document.getElementById('btn-apply-health-repairs')?.addEventListener('click', applyMultiYearDataRepairs);
