let excelWorkingRows = [];
let excelColumns = [];
let isExcelEditMode = false;

const getDynamicExcelSchemaFields = () => {
    const visible = getVisibleStudentFields(studentFieldSchema).filter(
        (f) => f.key !== 'photo' && f.key !== 'class'
    );
    return [
        ...visible.map((f) => ({
            key: f.key,
            label: `${f.label}${f.required ? ' *' : ''}`,
            required: Boolean(f.required),
            system: Boolean(f.system),
            type: f.type
        })),
        { key: 'none', label: '-- Skip / Ignore --' }
    ];
};

function getDuplicateMappedFields() {
    const counts = {};
    excelColumns.forEach(c => {
        if (c.mappedField && c.mappedField !== 'none') {
            counts[c.mappedField] = (counts[c.mappedField] || 0) + 1;
        }
    });
    const dupes = new Set();
    Object.entries(counts).forEach(([k, count]) => {
        if (count > 1) dupes.add(k);
    });
    return dupes;
}

