function normalizeToIsoDate(val) {
    if (val === null || val === undefined || val === '') return '';
    if (val instanceof Date && !isNaN(val.getTime())) {
        const y = val.getFullYear();
        const m = String(val.getMonth() + 1).padStart(2, '0');
        const d = String(val.getDate()).padStart(2, '0');
        return `${y}-${m}-${d}`;
    }
    const str = String(val).trim();
    if (!str) return '';

    // 1. Numeric Excel Date Serial (e.g. 43722)
    if (/^\d{4,5}(\.\d+)?$/.test(str)) {
        const num = parseFloat(str);
        if (num > 1000 && num < 100000) {
            const utcDays = Math.floor(num - 25569);
            const date = new Date(utcDays * 86400 * 1000);
            if (!isNaN(date.getTime())) {
                const y = date.getUTCFullYear();
                const m = String(date.getUTCMonth() + 1).padStart(2, '0');
                const d = String(date.getUTCDate()).padStart(2, '0');
                return `${y}-${m}-${d}`;
            }
        }
    }

    // 2. ISO format: YYYY-MM-DD or YYYY/MM/DD or YYYY.MM.DD
    const isoMatch = str.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})/);
    if (isoMatch) {
        const y = isoMatch[1];
        const m = isoMatch[2].padStart(2, '0');
        const d = isoMatch[3].padStart(2, '0');
        return `${y}-${m}-${d}`;
    }

    // 3. DD-MM-YYYY or DD/MM/YYYY or DD.MM.YYYY
    const dmyMatch = str.match(/^(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})/);
    if (dmyMatch) {
        const d = dmyMatch[1].padStart(2, '0');
        const m = dmyMatch[2].padStart(2, '0');
        const y = dmyMatch[3];
        return `${y}-${m}-${d}`;
    }

    // 4. Fallback Date parse
    const parsed = new Date(str);
    if (!isNaN(parsed.getTime()) && parsed.getFullYear() > 1900 && parsed.getFullYear() < 2100) {
        const y = parsed.getFullYear();
        const m = String(parsed.getMonth() + 1).padStart(2, '0');
        const d = String(parsed.getDate()).padStart(2, '0');
        return `${y}-${m}-${d}`;
    }

    return str;
}

function setExcelEditMode(enabled) {
    isExcelEditMode = enabled;
    const switchEl = document.getElementById('excel-edit-mode-switch');
    if (switchEl && switchEl.checked !== isExcelEditMode) {
        switchEl.checked = isExcelEditMode;
    }
    const statusLabel = document.getElementById('excel-edit-mode-status');
    const banner = document.getElementById('excel-edit-mode-banner');

    if (statusLabel) {
        if (isExcelEditMode) {
            statusLabel.textContent = "ON";
            statusLabel.className = "text-[11px] font-extrabold uppercase tracking-wider text-emerald-600 font-mono";
            if (banner) banner.classList.remove('hidden');
        } else {
            statusLabel.textContent = "OFF";
            statusLabel.className = "text-[11px] font-extrabold uppercase tracking-wider text-slate-500 font-mono";
            if (banner) banner.classList.add('hidden');
        }
    }

    renderExcelPreviewTable();
}

document.getElementById('excel-edit-mode-switch')?.addEventListener('change', (e) => {
    setExcelEditMode(e.target.checked);
});

function extractRowFields(rowIdx) {
    const workingRow = excelWorkingRows[rowIdx] || {};
    const extracted = {
        name: '', uid: '', father: '', mother: '', gender: '', adm: '',
        dob: '', admDate: '', status: '', adhaar: '', mobile: '',
        motherMobile: '', address: ''
    };
    excelColumns.forEach(c => {
        if (c.mappedField && c.mappedField !== 'none') {
            const rawVal = workingRow[c.id];
            if (rawVal !== undefined && rawVal !== null && String(rawVal).trim() !== '') {
                if (!extracted[c.mappedField]) {
                    extracted[c.mappedField] = String(rawVal).trim();
                }
            }
        }
    });
    return extracted;
}

function validateAndBuildStudent(extracted, rowIdx, selectedBulkClass, existingClassStudents) {
    const rawName = String(extracted.name || '').trim();
    const rawDob = extracted.dob;
    const dobVal = normalizeToIsoDate(rawDob);
    const rawAdmDate = extracted.admDate;
    const admDateVal = normalizeToIsoDate(rawAdmDate);
    const adhaarVal = String(extracted.adhaar || '').trim();
    const motherVal = String(extracted.mother || '').trim();
    const motherMobileVal = String(extracted.motherMobile || '').trim();
    const admVal = String(extracted.adm || '').toUpperCase().trim();
    const uidVal = String(extracted.uid || '').trim();
    const fatherVal = String(extracted.father || '').toUpperCase().trim();
    const mobileVal = String(extracted.mobile || '').trim();
    const addressVal = String(extracted.address || '').trim();
    const statusVal = normalizeStudentStatus(String(extracted.status || ''));
    const genderRaw = String(extracted.gender || '').toLowerCase().trim();
    const genderVal = genderRaw.startsWith('f') ? 'Female' : 'Male';

    const fieldStatuses = {};
    const omittedFields = [];
    const fatalReasons = [];

    fieldStatuses.class = { status: 'valid', val: selectedBulkClass };

    const hasFatalError = !rawName;
    if (hasFatalError) {
        fieldStatuses.name = { status: 'error', val: '', reason: 'Name is mandatory' };
        fatalReasons.push('Missing Student Name');
    } else {
        fieldStatuses.name = { status: 'valid', val: rawName.toUpperCase().trim() };
    }

    if (!genderRaw) {
        fieldStatuses.gender = { status: 'blank', val: genderVal, note: 'Defaulted to Male' };
    } else {
        fieldStatuses.gender = { status: 'valid', val: genderVal };
    }

    fieldStatuses.uid = uidVal ? { status: 'valid', val: uidVal } : { status: 'blank', val: '' };
    fieldStatuses.father = fatherVal ? { status: 'valid', val: fatherVal } : { status: 'blank', val: '' };
    fieldStatuses.mother = motherVal ? { status: 'valid', val: motherVal.toUpperCase() } : { status: 'blank', val: '' };
    fieldStatuses.adm = admVal ? { status: 'valid', val: admVal } : { status: 'blank', val: '' };

    let cleanDob = '';
    if (rawDob) {
        if (dobVal) {
            cleanDob = dobVal;
            fieldStatuses.dob = { status: 'valid', val: cleanDob };
        } else {
            fieldStatuses.dob = { status: 'error', val: String(rawDob), reason: 'Invalid date format (will be saved as blank)' };
            omittedFields.push('Date of Birth');
        }
    } else {
        fieldStatuses.dob = { status: 'blank', val: '' };
    }

    let cleanAdmDate = '';
    if (rawAdmDate) {
        if (admDateVal) {
            cleanAdmDate = admDateVal;
            fieldStatuses.admDate = { status: 'valid', val: cleanAdmDate };
        } else {
            fieldStatuses.admDate = { status: 'error', val: String(rawAdmDate), reason: 'Invalid date format (will be saved as blank)' };
            omittedFields.push('Date of Admission');
        }
    } else {
        fieldStatuses.admDate = { status: 'blank', val: '' };
    }

    fieldStatuses.status = { status: 'valid', val: statusVal };

    let cleanAadhaar = '';
    if (adhaarVal) {
        const digits = adhaarVal.replace(/\D/g, '');
        if (digits.length === 12) {
            cleanAadhaar = digits;
            fieldStatuses.adhaar = { status: 'valid', val: cleanAadhaar };
        } else {
            fieldStatuses.adhaar = { status: 'error', val: adhaarVal, reason: 'Invalid Aadhaar (must be 12 digits, will be skipped)' };
            omittedFields.push('Aadhaar Number');
        }
    } else {
        fieldStatuses.adhaar = { status: 'blank', val: '' };
    }

    let cleanMobile = '';
    if (mobileVal) {
        const digits = mobileVal.replace(/\D/g, '');
        if (digits.length >= 10 && digits.length <= 15) {
            cleanMobile = digits;
            fieldStatuses.mobile = { status: 'valid', val: cleanMobile };
        } else {
            fieldStatuses.mobile = { status: 'error', val: mobileVal, reason: 'Invalid Mobile Number (will be skipped)' };
            omittedFields.push("Father's Phone Number");
        }
    } else {
        fieldStatuses.mobile = { status: 'blank', val: '' };
    }

    let cleanMotherMobile = '';
    if (motherMobileVal) {
        const digits = motherMobileVal.replace(/\D/g, '');
        if (digits.length >= 10 && digits.length <= 15) {
            cleanMotherMobile = digits;
            fieldStatuses.motherMobile = { status: 'valid', val: cleanMotherMobile };
        } else {
            fieldStatuses.motherMobile = { status: 'error', val: motherMobileVal, reason: 'Invalid Mother Mobile Number (will be skipped)' };
            omittedFields.push("Mother's Phone Number");
        }
    } else {
        fieldStatuses.motherMobile = { status: 'blank', val: '' };
    }

    fieldStatuses.address = addressVal ? { status: 'valid', val: addressVal } : { status: 'blank', val: '' };

    // Extract & validate visible custom fields
    const customFieldsData = {};
    const customDefs = getCustomStudentFields(studentFieldSchema, { onlyVisible: true });
    customDefs.forEach((cf) => {
        const rawVal = extracted[cf.key] !== undefined && extracted[cf.key] !== null ? String(extracted[cf.key]).trim() : '';
        if (!rawVal) {
            fieldStatuses[cf.key] = { status: 'blank', val: '' };
            customFieldsData[cf.key] = '';
            return;
        }
        if (cf.type === 'phone') {
            const digits = rawVal.replace(/\D/g, '');
            if (digits.length >= 10 && digits.length <= 15) {
                customFieldsData[cf.key] = digits;
                fieldStatuses[cf.key] = { status: 'valid', val: digits };
            } else {
                customFieldsData[cf.key] = '';
                fieldStatuses[cf.key] = { status: 'error', val: rawVal, reason: `Invalid ${cf.label} (will be skipped)` };
                omittedFields.push(cf.label);
            }
        } else if (cf.type === 'date') {
            const iso = normalizeToIsoDate(rawVal);
            if (iso) {
                customFieldsData[cf.key] = iso;
                fieldStatuses[cf.key] = { status: 'valid', val: iso };
            } else {
                customFieldsData[cf.key] = '';
                fieldStatuses[cf.key] = { status: 'error', val: rawVal, reason: `Invalid date format for ${cf.label} (will be skipped)` };
                omittedFields.push(cf.label);
            }
        } else {
            customFieldsData[cf.key] = rawVal;
            fieldStatuses[cf.key] = { status: 'valid', val: rawVal };
        }
    });

    const studentObj = {
        name: rawName ? rawName.toUpperCase().trim() : '',
        gender: genderVal,
        class: selectedBulkClass,
        studentClass: selectedBulkClass,
        uid: uidVal,
        father: fatherVal,
        mother: motherVal ? motherVal.toUpperCase() : '',
        adm: admVal,
        dob: cleanDob,
        admDate: cleanAdmDate,
        status: statusVal,
        adhaar: cleanAadhaar,
        mobile: cleanMobile,
        motherMobile: cleanMotherMobile,
        samastha: uidVal,
        samasthaId: uidVal,
        address: addressVal,
        customFields: customFieldsData,
        photoUrl: '',
        academicYear: getActiveAcademicYearLabel(),
        fees: {},
        rowIdx: rowIdx,
        hasFatalError: hasFatalError,
        hasOmittedFields: omittedFields.length > 0,
        omittedFields: omittedFields,
        fatalReasons: fatalReasons,
        fieldStatuses: fieldStatuses
    };

    const candAdm = studentObj.adm;
    const candName = studentObj.name;
    const candUid = studentObj.uid;
    const candMobile = studentObj.mobile;

    const existingMatch = existingClassStudents.find(exist => {
        const existAdm = String(exist.adm || '').toUpperCase().trim();
        const existName = String(exist.name || '').toUpperCase().trim();
        const existUid = String(exist.uid || '').toUpperCase().trim();
        const existMobile = String(exist.mobile || '').trim();

        if (candAdm && existAdm && candAdm === existAdm) return true;
        if (candUid && existUid && candUid === existUid) return true;
        if (candName && existName && candName === existName) {
            if (candMobile && existMobile && candMobile === existMobile) return true;
            if (!candAdm && !existAdm) return true;
        }
        return false;
    });

    studentObj.existingMatch = existingMatch || null;
    studentObj.isDuplicate = !!existingMatch;

    return studentObj;
}

function recalculateExcelStats() {
    const totalCount = excelParsedData.length;
    const validStudents = excelParsedData.filter(s => !s.hasFatalError);
    const completelyValidStudents = excelParsedData.filter(s => !s.hasFatalError && (s.omittedFields?.length || 0) === 0);
    const fatalRows = excelParsedData.filter(s => s.hasFatalError);
    const validCount = validStudents.length;
    const completelyValidCount = completelyValidStudents.length;
    const fatalCount = fatalRows.length;
    const totalOmittedFields = validStudents.reduce((acc, s) => acc + (s.omittedFields?.length || 0), 0);
    const mergeCount = validStudents.filter(s => s.isDuplicate).length;

    const statTotal = document.getElementById('stat-total-records');
    const statValid = document.getElementById('stat-valid-records');
    const statIssue = document.getElementById('stat-issue-records');
    const statMerge = document.getElementById('stat-merge-records');
    if (statTotal) statTotal.textContent = totalCount;
    if (statValid) statValid.textContent = completelyValidCount;
    if (statIssue) {
        if (fatalCount > 0 && totalOmittedFields > 0) {
            statIssue.textContent = `${fatalCount} Fatal (${totalOmittedFields} skipped)`;
        } else if (fatalCount > 0) {
            statIssue.textContent = `${fatalCount} Fatal`;
        } else if (totalOmittedFields > 0) {
            statIssue.textContent = `${totalOmittedFields} fields skipped`;
        } else {
            statIssue.textContent = '0';
        }
    }
    if (statMerge) statMerge.textContent = mergeCount;

    const duplicateFields = getDuplicateMappedFields();
    const hasDuplicateMapping = duplicateFields.size > 0;

    const startBtn = document.getElementById('start-upload-btn');
    const startBtnText = document.getElementById('start-upload-btn-text');
    const skipBtn = document.getElementById('skip-issues-upload-btn');
    const validOnlyCountSpan = document.getElementById('valid-only-count');

    if (hasDuplicateMapping) {
        if (startBtn) {
            startBtn.disabled = true;
            if (startBtnText) startBtnText.textContent = 'Cannot Upload (Duplicate Column Mapped)';
        }
        if (skipBtn) {
            skipBtn.disabled = true;
        }
    } else if (validCount === 0) {
        if (startBtn) {
            startBtn.disabled = true;
            if (startBtnText) startBtnText.textContent = 'Cannot Upload (Missing Names)';
        }
        if (skipBtn) {
            skipBtn.classList.add('hidden');
            skipBtn.disabled = true;
        }
    } else {
        if (startBtn) {
            startBtn.disabled = false;
            if (startBtnText) {
                startBtnText.textContent = `Upload All (${validCount})`;
            }
        }
        if (skipBtn) {
            skipBtn.classList.remove('hidden');
            if (validOnlyCountSpan) validOnlyCountSpan.textContent = completelyValidCount;
            skipBtn.disabled = completelyValidCount === 0;
        }
    }

    const dupContainer = document.getElementById('duplicate-policy-container');
    const dupDetectedCount = document.getElementById('duplicate-detected-count');
    if (dupContainer) {
        if (mergeCount > 0) {
            dupContainer.classList.remove('hidden');
            if (dupDetectedCount) dupDetectedCount.textContent = mergeCount;
        } else {
            dupContainer.classList.add('hidden');
        }
    }
}

function updateRowDomAfterEdit(rowIdx) {
    const tr = document.getElementById(`excel-preview-row-${rowIdx}`);
    if (!tr) return;
    const s = excelParsedData[rowIdx];
    if (!s) return;

    tr.className = s.hasFatalError 
        ? 'bg-red-100 hover:bg-red-200/90 font-semibold text-red-950 border-b border-red-300 transition-colors' 
        : (s.hasOmittedFields 
            ? 'bg-amber-100/70 hover:bg-amber-200/70 font-medium text-amber-950 border-b border-amber-300 transition-colors' 
            : (s.isDuplicate 
                ? 'bg-blue-100 hover:bg-blue-200/80 font-medium text-blue-950 border-b border-blue-300 transition-colors' 
                : 'hover:bg-slate-50 transition-colors border-b border-slate-100'));

    const statusCell = tr.querySelector('.excel-row-status-cell');
    if (statusCell) {
        if (s.hasFatalError) {
            statusCell.innerHTML = `<span class="px-2.5 py-1 rounded-md text-[10px] font-black bg-red-600 text-white shadow-xs" title="${escapeHtml(s.fatalReasons.join(', '))}">FATAL</span>`;
        } else if (s.hasOmittedFields) {
            statusCell.innerHTML = `<span class="px-2.5 py-1 rounded-md text-[10px] font-black bg-amber-500 text-white shadow-xs" title="Valid student (${s.omittedFields.length} invalid field(s) skipped: ${escapeHtml(s.omittedFields.join(', '))})">READY (${s.omittedFields.length} SKIPPED)</span>`;
        } else if (s.isDuplicate) {
            statusCell.innerHTML = `<span class="px-2.5 py-1 rounded-md text-[10px] font-black bg-blue-600 text-white shadow-xs" title="Matches existing student in this class">EXISTING</span>`;
        } else {
            statusCell.innerHTML = `<span class="px-2.5 py-1 rounded-md text-[10px] font-black bg-emerald-600 text-white shadow-xs">READY</span>`;
        }
    }

    excelColumns.forEach(c => {
        const td = tr.querySelector(`.excel-cell[data-col-id="${c.id}"]`);
        if (!td) return;
        const mappedField = c.mappedField;
        if (mappedField && mappedField !== 'none') {
            const fStatus = s.fieldStatuses?.[mappedField];
            if (fStatus?.status === 'error') {
                td.classList.add('bg-red-200', 'text-red-950', 'border-2', 'border-red-500', 'font-black');
                td.classList.remove('bg-amber-100', 'text-amber-950', 'border-amber-300');
                td.title = fStatus.reason || 'Invalid data';
            } else if (fStatus?.status === 'blank') {
                td.classList.add('bg-amber-100', 'text-amber-950', 'border', 'border-amber-300', 'font-semibold');
                td.classList.remove('bg-red-200', 'text-red-950', 'border-2', 'border-red-500', 'font-black');
                td.title = 'Blank / Not provided';
            } else {
                td.classList.remove('bg-red-200', 'text-red-950', 'border-2', 'border-red-500', 'font-black', 'bg-amber-100', 'text-amber-950', 'border-amber-300');
                td.title = '';
            }
        }
    });

    recalculateExcelStats();
}

function openAddFieldModal() {
    const modal = document.getElementById('excel-add-field-modal');
    const listContainer = document.getElementById('excel-add-field-list');
    if (!modal || !listContainer) return;

    const currentlyMapped = new Set(excelColumns.map(c => c.mappedField));
    const schemaFields = getDynamicExcelSchemaFields();
    const unmappedFields = schemaFields.filter(f => f.key !== 'none' && !currentlyMapped.has(f.key));

    if (unmappedFields.length === 0) {
        listContainer.innerHTML = `
            <div class="p-4 bg-emerald-50 border border-emerald-200 rounded-xl text-center">
                <i class="fas fa-check-circle text-emerald-600 text-2xl mb-1.5"></i>
                <div class="text-xs font-bold text-emerald-900">All Active Student Fields Present</div>
                <div class="text-[11px] text-emerald-700 mt-0.5">All configured student fields are already present in the spreadsheet.</div>
            </div>
        `;
    } else {
        listContainer.innerHTML = unmappedFields.map(field => `
            <button type="button" class="excel-add-field-option-btn w-full p-2.5 bg-slate-50 hover:bg-blue-50 border border-slate-200 hover:border-blue-300 rounded-xl text-left transition flex items-center justify-between group cursor-pointer" data-field-key="${field.key}" data-field-label="${escapeHtml(field.label)}">
                <div class="flex items-center gap-2.5">
                    <div class="w-7 h-7 rounded-lg bg-blue-100 text-blue-700 flex items-center justify-center text-xs group-hover:bg-blue-600 group-hover:text-white transition">
                        <i class="fas fa-plus"></i>
                    </div>
                    <div>
                        <div class="text-xs font-bold text-slate-800 group-hover:text-blue-900">${escapeHtml(field.label)}</div>
                        <div class="text-[10px] text-slate-500 font-mono">Key: ${field.key}</div>
                    </div>
                </div>
                <span class="text-xs font-bold text-blue-600 opacity-0 group-hover:opacity-100 transition flex items-center gap-1">Add <i class="fas fa-chevron-right text-[10px]"></i></span>
            </button>
        `).join('');
    }

    modal.classList.remove('hidden');
    modal.classList.add('flex');
}

function closeAddFieldModal() {
    const modal = document.getElementById('excel-add-field-modal');
    if (modal) {
        modal.classList.add('hidden');
        modal.classList.remove('flex');
    }
}

function renderExcelPreviewTable() {
    const previewContainer = document.getElementById('excel-preview-table-container');
    if (!previewContainer) return;

    if (!excelParsedData || excelParsedData.length === 0) {
        previewContainer.innerHTML = '';
        previewContainer.classList.add('hidden');
        return;
    }

    const duplicateFields = getDuplicateMappedFields();
    const hasDuplicateMapping = duplicateFields.size > 0;
    const schemaFields = getDynamicExcelSchemaFields();
    const duplicateLabels = Array.from(duplicateFields).map(f => {
        return schemaFields.find(s => s.key === f)?.label?.replace('*', '').trim() || f;
    });

    const mappedCount = excelColumns.filter(c => c.mappedField && c.mappedField !== 'none').length;
    const skippedCount = excelColumns.length - mappedCount;

    let duplicateAlertHtml = '';
    if (hasDuplicateMapping) {
        duplicateAlertHtml = `
            <div class="p-3 mb-2 bg-red-600 text-white rounded-xl shadow-md flex items-center justify-between gap-3 text-xs font-bold animate-pulse">
                <div class="flex items-center gap-2">
                    <i class="fas fa-exclamation-triangle text-lg shrink-0"></i>
                    <div>
                        <div class="font-black text-sm">Duplicate Column Mapping Detected!</div>
                        <div class="font-normal text-red-100 text-[11px]">The field(s) <b>${escapeHtml(duplicateLabels.join(', '))}</b> are assigned to multiple columns. Each field can only be assigned once. Highlighted solid red columns must be changed or set to Skip before uploading.</div>
                    </div>
                </div>
            </div>
        `;
    }

    let html = `
        ${duplicateAlertHtml}
        <div class="px-3 py-2 bg-slate-100/90 border-b border-slate-200 text-xs font-semibold text-slate-800 flex flex-wrap justify-between items-center gap-2">
            <div class="flex items-center gap-2">
                <i class="fas fa-file-spreadsheet text-emerald-600"></i>
                <span>Complete Spreadsheet Preview (${excelParsedData.length} records)</span>
                <span class="text-[11px] font-normal text-slate-600 bg-white px-2 py-0.5 rounded border border-slate-200">
                    ${mappedCount} Columns Mapped, ${skippedCount} Skipped
                </span>
                ${hasDuplicateMapping ? '<span class="text-[11px] font-bold text-white bg-red-600 px-2 py-0.5 rounded shadow-2xs">Duplicate Collision</span>' : ''}
            </div>
            <div class="flex items-center gap-2 text-xs">
                ${isExcelEditMode 
                    ? '<span class="text-emerald-700 font-bold flex items-center gap-1.5"><i class="fas fa-edit"></i> Edit & Mapping Mode Active: Click cells to edit, change dropdowns to remap</span>' 
                    : '<span class="text-slate-500 flex items-center gap-1.5"><i class="fas fa-lock text-slate-400"></i> Standard View (Turn ON switch above to edit cells or remap headers)</span>'}
            </div>
        </div>
        <div class="overflow-x-auto max-h-[460px] overflow-y-auto">
            <table class="w-full text-xs text-left text-slate-700 border-collapse border-slate-200">
                <thead class="bg-slate-100 text-slate-700 font-bold sticky top-0 z-20 shadow-sm border-b-2 border-slate-300">
                    <tr>
                        <th class="p-2 border-b border-r bg-slate-100 text-center w-10 text-slate-500 font-mono">#</th>
                        <th class="p-2 border-b border-r bg-slate-100 text-center w-24">
                            <span class="block text-[11px] uppercase tracking-wider text-slate-600">Status</span>
                        </th>
                        ${excelColumns.map(col => {
                            const isDup = duplicateFields.has(col.mappedField);
                            const isSkipped = col.mappedField === 'none';
                            let headerBg = '';
                            let selectStyleClass = '';

                            if (isDup) {
                                headerBg = 'bg-red-600 text-white border-2 border-red-700 shadow-sm';
                                selectStyleClass = 'bg-red-700 text-white border-2 border-white font-extrabold shadow-sm focus:ring-2 focus:ring-white';
                            } else if (isSkipped) {
                                headerBg = 'bg-slate-50 text-slate-500';
                                selectStyleClass = !isExcelEditMode
                                    ? 'opacity-60 cursor-not-allowed pointer-events-none bg-slate-100 border-slate-200 text-slate-500'
                                    : 'border-slate-300 text-slate-600 bg-white font-medium';
                            } else {
                                headerBg = 'bg-slate-100 text-slate-800';
                                selectStyleClass = !isExcelEditMode
                                    ? 'opacity-60 cursor-not-allowed pointer-events-none bg-slate-100 border-slate-200 text-slate-500'
                                    : 'border-blue-400 text-blue-900 font-bold bg-white';
                            }

                            const disabledAttr = !isExcelEditMode ? 'disabled' : '';

                            return `
                                <th class="p-2 border-b border-r ${headerBg} min-w-[165px] max-w-[230px]">
                                    <div class="flex items-center justify-between gap-1 mb-1">
                                        <span class="text-[11px] font-mono ${isDup ? 'text-white font-extrabold' : 'text-slate-700'} truncate" title="${escapeHtml(col.header)}">
                                            ${escapeHtml(col.header)}
                                        </span>
                                        ${isDup 
                                            ? '<span class="text-[9px] px-1.5 py-0.5 bg-white text-red-700 font-black rounded uppercase shadow-xs flex items-center gap-1"><i class="fas fa-exclamation-circle"></i> DUPLICATE</span>' 
                                            : (isSkipped ? '<span class="text-[9px] px-1 bg-slate-200 text-slate-600 rounded">SKIP</span>' : '')}
                                    </div>
                                    <select class="excel-col-map-dropdown w-full p-1 border ${selectStyleClass} rounded text-[11px] shadow-2xs focus:ring-1 focus:ring-blue-500" data-col-id="${col.id}" ${disabledAttr}>
                                        ${schemaFields.map(f => `
                                            <option value="${f.key}" ${col.mappedField === f.key ? 'selected' : ''}>
                                                ${escapeHtml(f.label)}
                                            </option>
                                        `).join('')}
                                    </select>
                                </th>
                            `;
                        }).join('')}
                        <th class="p-2 border-b bg-slate-100 text-center w-28">
                            <button type="button" id="excel-add-col-btn" class="${!isExcelEditMode ? 'hidden' : ''} px-2.5 py-1.5 bg-blue-50 hover:bg-blue-100 text-blue-700 border border-blue-200 rounded text-xs font-semibold whitespace-nowrap transition flex items-center gap-1 mx-auto shadow-2xs cursor-pointer">
                                <i class="fas fa-plus-circle text-blue-600"></i> Add Field
                            </button>
                        </th>
                    </tr>
                </thead>
                <tbody class="divide-y divide-slate-100 font-sans">
                    ${excelParsedData.map((s, idx) => {
                        const workingRow = excelWorkingRows[idx] || {};
                        let rowBg = 'hover:bg-slate-50 border-b border-slate-100';
                        let statusBadge = '';
                        
                        if (s.hasFatalError) {
                            rowBg = 'bg-red-100 hover:bg-red-200/90 font-semibold text-red-950 border-b border-red-300';
                            statusBadge = `<span class="px-2.5 py-1 rounded-md text-[10px] font-black bg-red-600 text-white shadow-xs" title="${escapeHtml(s.fatalReasons.join(', '))}">FATAL</span>`;
                        } else if (s.hasOmittedFields) {
                            rowBg = 'bg-amber-100/70 hover:bg-amber-200/70 font-medium text-amber-950 border-b border-amber-300';
                            statusBadge = `<span class="px-2.5 py-1 rounded-md text-[10px] font-black bg-amber-500 text-white shadow-xs" title="Valid student (${s.omittedFields.length} invalid field(s) skipped: ${escapeHtml(s.omittedFields.join(', '))})">READY (${s.omittedFields.length} SKIPPED)</span>`;
                        } else if (s.isDuplicate) {
                            rowBg = 'bg-blue-100 hover:bg-blue-200/80 font-medium text-blue-950 border-b border-blue-300';
                            statusBadge = `<span class="px-2.5 py-1 rounded-md text-[10px] font-black bg-blue-600 text-white shadow-xs" title="Matches existing student in this class">EXISTING</span>`;
                        } else {
                            statusBadge = `<span class="px-2.5 py-1 rounded-md text-[10px] font-black bg-emerald-600 text-white shadow-xs">READY</span>`;
                        }

                        return `
                            <tr id="excel-preview-row-${idx}" class="${rowBg} transition-colors">
                                <td class="p-2 text-center text-slate-500 border-b border-r border-slate-200 font-mono text-xs">${idx + 1}</td>
                                <td class="excel-row-status-cell p-2 border-b border-r border-slate-200 text-center whitespace-nowrap">${statusBadge}</td>
                                ${excelColumns.map(col => {
                                    const val = workingRow[col.id] !== undefined && workingRow[col.id] !== null ? String(workingRow[col.id]) : '';
                                    const isSkipped = col.mappedField === 'none';
                                    let bgClass = '';
                                    let titleAttr = '';
                                    
                                    if (isSkipped) {
                                        bgClass = 'bg-slate-50/50 text-slate-400 italic';
                                        titleAttr = 'title="Column skipped from import"';
                                    } else {
                                        const fStatus = s.fieldStatuses?.[col.mappedField];
                                        if (fStatus?.status === 'error') {
                                            bgClass = 'bg-red-200 text-red-950 border-2 border-red-500 font-black';
                                            titleAttr = `title="${escapeHtml(fStatus.reason || 'Invalid data')}"`;
                                        } else if (fStatus?.status === 'blank' || !val.trim()) {
                                            bgClass = 'bg-amber-100 text-amber-950 border border-amber-300 font-semibold';
                                            titleAttr = 'title="Blank / Not provided"';
                                        }
                                    }

                                    const editAttrs = isExcelEditMode 
                                        ? 'contenteditable="true" class="excel-cell p-2 border-b border-r border-slate-200 whitespace-nowrap cursor-text focus:outline focus:outline-2 focus:outline-emerald-500 focus:bg-white focus:z-10 transition-all font-mono text-xs ' + bgClass + '"'
                                        : 'class="excel-cell p-2 border-b border-r border-slate-200 whitespace-nowrap text-xs ' + bgClass + '"';

                                    const displayVal = val.trim() ? escapeHtml(val) : '';

                                    return `<td ${editAttrs} data-row-idx="${idx}" data-col-id="${col.id}" ${titleAttr}>${displayVal}</td>`;
                                }).join('')}
                                <td class="p-2 border-b border-slate-200 bg-slate-50/30"></td>
                            </tr>
                        `;
                    }).join('')}
                </tbody>
            </table>
        </div>
    `;

    previewContainer.innerHTML = html;
    previewContainer.classList.remove('hidden');
}

function rebuildAllExcelDataAndRender() {
    const selectedBulkClass = (document.getElementById('bulk-upload-class')?.value || '').toUpperCase().trim();
    const existingClassStudents = students.filter(st => String(st.class || '').toUpperCase().trim() === selectedBulkClass);

    excelParsedData = excelWorkingRows.map((_, rowIdx) => {
        const extracted = extractRowFields(rowIdx);
        return validateAndBuildStudent(extracted, rowIdx, selectedBulkClass, existingClassStudents);
    });

    recalculateExcelStats();
    renderExcelPreviewTable();
}

function decodeCsvBuffer(arrayBuffer) {
    const bytes = new Uint8Array(arrayBuffer);
    let text = '';
    if (bytes.length >= 2 && bytes[0] === 0xFF && bytes[1] === 0xFE) {
        text = new TextDecoder('utf-16le').decode(bytes.subarray(2));
    } else if (bytes.length >= 2 && bytes[0] === 0xFE && bytes[1] === 0xFF) {
        text = new TextDecoder('utf-16be').decode(bytes.subarray(2));
    } else if (bytes.length >= 3 && bytes[0] === 0xEF && bytes[1] === 0xBB && bytes[2] === 0xBF) {
        text = new TextDecoder('utf-8').decode(bytes.subarray(3));
    } else {
        text = new TextDecoder('utf-8', { fatal: false }).decode(bytes);
        if (text.includes('\u0000')) {
            text = new TextDecoder('utf-16le').decode(bytes);
        }
    }
    return text.replace(/^\uFEFF/, '').replace(/\r\n/g, '\n').replace(/\r/g, '\n');
}

function detectCsvDelimiter(text) {
    const lines = text.split('\n');
    const headerLine = lines.find((line) => line.trim() !== '') || '';
    const counts = { ',': 0, ';': 0, '\t': 0 };
    let inQuotes = false;
    for (let i = 0; i < headerLine.length; i += 1) {
        const ch = headerLine[i];
        if (ch === '"') {
            if (inQuotes && headerLine[i + 1] === '"') {
                i += 1;
            } else {
                inQuotes = !inQuotes;
            }
        } else if (!inQuotes && Object.prototype.hasOwnProperty.call(counts, ch)) {
            counts[ch] += 1;
        }
    }
    if (counts[';'] > counts[','] && counts[';'] >= counts['\t']) return ';';
    if (counts['\t'] > counts[','] && counts['\t'] > counts[';']) return '\t';
    return ',';
}

function parseCsvMatrix(text, delimiter) {
    const rows = [];
    let currentRow = [];
    let currentCell = '';
    let inQuotes = false;

    for (let i = 0; i < text.length; i += 1) {
        const ch = text[i];
        if (inQuotes) {
            if (ch === '"') {
                if (text[i + 1] === '"') {
                    currentCell += '"';
                    i += 1;
                } else {
                    inQuotes = false;
                }
            } else {
                currentCell += ch;
            }
        } else if (ch === '"') {
            inQuotes = true;
        } else if (ch === delimiter) {
            currentRow.push(currentCell);
            currentCell = '';
        } else if (ch === '\n') {
            currentRow.push(currentCell);
            if (currentRow.some((cell) => String(cell).trim() !== '')) {
                rows.push(currentRow);
            }
            currentRow = [];
            currentCell = '';
        } else {
            currentCell += ch;
        }
    }

    if (currentCell.length > 0 || currentRow.length > 0) {
        currentRow.push(currentCell);
        if (currentRow.some((cell) => String(cell).trim() !== '')) {
            rows.push(currentRow);
        }
    }
    return rows;
}

function parseCsvArrayBufferToObjects(arrayBuffer) {
    const text = decodeCsvBuffer(arrayBuffer);
    if (!text.trim()) return [];
    const delimiter = detectCsvDelimiter(text);
    const matrix = parseCsvMatrix(text, delimiter);
    if (matrix.length < 2) return [];

    const rawHeaders = matrix[0];
    const usedHeaders = new Set();
    const headers = rawHeaders.map((h, idx) => {
        const cleaned = String(h || '').trim();
        let candidate = cleaned || `Column ${idx + 1}`;
        let suffix = 2;
        while (usedHeaders.has(candidate)) {
            candidate = `${cleaned || `Column ${idx + 1}`} (${suffix})`;
            suffix += 1;
        }
        usedHeaders.add(candidate);
        return candidate;
    });

    const objects = [];
    for (let r = 1; r < matrix.length; r += 1) {
        const cells = matrix[r];
        const rowObj = {};
        let hasAnyValue = false;
        headers.forEach((header, idx) => {
            const val = cells[idx] !== undefined && cells[idx] !== null ? String(cells[idx]).trim() : '';
            if (val !== '') hasAnyValue = true;
            rowObj[header] = val;
        });
        if (hasAnyValue) objects.push(rowObj);
    }
    return objects;
}

function formatSpreadsheetCellValue(val) {
    if (val === undefined || val === null) return '';
    if (val instanceof Date && !isNaN(val.getTime())) {
        return normalizeToIsoDate(val);
    }
    return String(val).trim();
}

function handleExcelFile(file) {
    const selectedBulkClass = (document.getElementById('bulk-upload-class')?.value || '').toUpperCase().trim();
    if (!selectedBulkClass) {
        alert('Please select a target class first.');
        if (fileInput) fileInput.value = '';
        return;
    }

    const fileName = String(file?.name || '');
    const ext = fileName.includes('.') ? fileName.split('.').pop().toLowerCase() : '';
    const mime = String(file?.type || '').toLowerCase();
    const isCsv = ext === 'csv' || (!ext && (mime.includes('csv') || mime === 'text/plain'));
    const isExcel = !isCsv && (ext === 'xlsx' || ext === 'xls' || mime.includes('spreadsheetml') || mime.includes('ms-excel'));

    if (!isCsv && !isExcel) {
        alert('Unsupported file format. Please upload a .xlsx, .xls, or .csv file.');
        if (fileInput) fileInput.value = '';
        return;
    }

    document.getElementById('excel-file-name').textContent = fileName;
    const fileIconEl = document.getElementById('excel-file-icon');
    if (fileIconEl) {
        fileIconEl.className = isCsv
            ? 'fas fa-file-csv text-blue-600 text-lg'
            : 'fas fa-file-excel text-emerald-600 text-lg';
    }

    const reader = new FileReader();
    reader.onload = (e) => {
        try {
            let rawData = [];
            if (isCsv) {
                rawData = parseCsvArrayBufferToObjects(e.target.result);
            } else {
                if (typeof XLSX === 'undefined') {
                    alert('Spreadsheet library is still loading. Please try again in a moment.');
                    if (fileInput) fileInput.value = '';
                    return;
                }
                const data = new Uint8Array(e.target.result);
                const workbook = XLSX.read(data, { type: 'array', cellDates: true });
                if (!workbook.SheetNames || workbook.SheetNames.length === 0) {
                    alert('No worksheets found in the uploaded file.');
                    if (fileInput) fileInput.value = '';
                    return;
                }
                const sheetRows = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]], { defval: "" });
                rawData = sheetRows.filter((row) =>
                    Object.values(row).some((val) => val !== undefined && val !== null && String(val).trim() !== '')
                );
            }

            if (rawData.length === 0) {
                alert('File is empty or has no student data rows.');
                if (fileInput) fileInput.value = '';
                return;
            }

            const normalizeHeader = (value = '') => value.toString().toLowerCase().replace(/[^a-z0-9]/g, '');
            const aliasMap = {
                name: ['name', 'studentname', 'student', 'fullname', 'nameofstudent'],
                uid: ['iduid', 'id', 'uid', 'samastha', 'samasthaid', 'samasthano', 'regno', 'registrationno', 'rollno', 'rollnumber', 'roll', 'studentid'],
                father: ['fathersname', 'fathername', 'father', 'parent', 'fatherguardian', 'guardian', 'fatherguardiansname'],
                mother: ['mothersname', 'mothername', 'mother'],
                gender: ['gender', 'sex'],
                adm: ['admno', 'admissionno', 'admissionnumber', 'adm', 'admn', 'admno.', 'admnumber', 'admissionnum'],
                dob: ['dob', 'dateofbirth', 'birthdate', 'birth', 'studentdob', 'dobddmmyyyy', 'dateofbirthddmmyyyy'],
                admDate: ['admdate', 'dateofadmission', 'admissiondate', 'admnsdate', 'admldate', 'joiningdate', 'admissiondateddmmyyyy', 'admdateddmmyyyy', 'doj'],
                status: ['studentstatus', 'status', 'state'],
                adhaar: ['aadhaar', 'adhaar', 'aadharno', 'aadhaarnumber', 'adhaarnumber', 'uidai', 'aadharno.', 'aadhaarno'],
                mobile: ['fathersphonenumber', 'fathersphone', 'fatherphone', 'mobile', 'phone', 'mobileno', 'phonenumber', 'contact', 'contactno', 'whatsapp'],
                motherMobile: ['mothersphonenumber', 'mothersphone', 'mothermobile', 'motherphone', 'motherphonenumber'],
                address: ['permanentaddress', 'address', 'permanent', 'addr', 'residentialaddress']
            };
            // Include configured field labels & custom fields in auto-mapping
            getVisibleStudentFields(studentFieldSchema).forEach((f) => {
                if (f.key === 'photo' || f.key === 'class') return;
                const normLabel = normalizeHeader(f.label);
                const normKey = normalizeHeader(f.key);
                if (!aliasMap[f.key]) aliasMap[f.key] = [];
                if (normLabel && !aliasMap[f.key].includes(normLabel)) aliasMap[f.key].push(normLabel);
                if (normKey && !aliasMap[f.key].includes(normKey)) aliasMap[f.key].push(normKey);
            });

            const detectedHeaders = [];
            rawData.forEach(row => {
                Object.keys(row).forEach(k => {
                    if (!detectedHeaders.includes(k)) detectedHeaders.push(k);
                });
            });

            const mappedTargets = new Set();
            excelColumns = detectedHeaders.map((header, idx) => {
                const norm = normalizeHeader(header);
                let matchedKey = 'none';
                for (const [targetKey, aliases] of Object.entries(aliasMap)) {
                    if (aliases.includes(norm) || aliases.some(a => (norm.startsWith(a) && (norm.includes('date') || norm.includes('dob') || norm.includes('no'))))) {
                        if (!mappedTargets.has(targetKey)) {
                            matchedKey = targetKey;
                            mappedTargets.add(targetKey);
                            break;
                        }
                    }
                }
                return {
                    id: `col_${idx}`,
                    header: header,
                    mappedField: matchedKey
                };
            });

            excelWorkingRows = rawData.map(rawRow => {
                const row = {};
                excelColumns.forEach(c => {
                    row[c.id] = formatSpreadsheetCellValue(rawRow[c.header]);
                });
                return row;
            });

            isExcelEditMode = false;
            setExcelEditMode(false);
            rebuildAllExcelDataAndRender();

            document.getElementById('excel-drop-zone').classList.add('hidden');
            document.getElementById('excel-preview-area').classList.remove('hidden');
            document.getElementById('upload-progress-bar').classList.add('hidden');
            document.getElementById('upload-status-text').textContent = "Ready to upload";
        } catch (err) {
            console.error("Error parsing spreadsheet file:", err);
            alert("Error reading file: " + (err.message || err));
            if (fileInput) fileInput.value = '';
        }
    };
    reader.onerror = () => {
        alert('Failed to read the selected file. Please try again.');
        if (fileInput) fileInput.value = '';
    };
    reader.readAsArrayBuffer(file);
}

// Table Container delegated events (Dropdown changes, cell edits, keyboard navigation)
const excelTableContainer = document.getElementById('excel-preview-table-container');
if (excelTableContainer) {
    excelTableContainer.addEventListener('change', (e) => {
        const select = e.target.closest('.excel-col-map-dropdown');
        if (!select) return;
        const colId = select.dataset.colId;
        const newField = select.value;
        const targetCol = excelColumns.find(c => c.id === colId);
        if (targetCol) {
            targetCol.mappedField = newField;
            rebuildAllExcelDataAndRender();
        }
    });

    excelTableContainer.addEventListener('blur', (e) => {
        const cell = e.target.closest('.excel-cell');
        if (!cell || !isExcelEditMode) return;
        const rowIdx = parseInt(cell.dataset.rowIdx, 10);
        const colId = cell.dataset.colId;
        if (isNaN(rowIdx) || !colId) return;

        const newText = cell.innerText.trim();
        if (excelWorkingRows[rowIdx]) {
            excelWorkingRows[rowIdx][colId] = newText;
            const extracted = extractRowFields(rowIdx);
            const selectedBulkClass = (document.getElementById('bulk-upload-class')?.value || '').toUpperCase().trim();
            const existingClassStudents = students.filter(st => String(st.class || '').toUpperCase().trim() === selectedBulkClass);
            excelParsedData[rowIdx] = validateAndBuildStudent(extracted, rowIdx, selectedBulkClass, existingClassStudents);
            updateRowDomAfterEdit(rowIdx);
        }
    }, true);

    excelTableContainer.addEventListener('keydown', (e) => {
        const cell = e.target.closest('.excel-cell');
        if (!cell || !isExcelEditMode) return;
        if (e.key === 'Enter') {
            e.preventDefault();
            const rowIdx = parseInt(cell.dataset.rowIdx, 10);
            const colId = cell.dataset.colId;
            const nextCell = document.querySelector(`.excel-cell[data-row-idx="${rowIdx + 1}"][data-col-id="${colId}"]`);
            if (nextCell) {
                nextCell.focus();
            } else {
                cell.blur();
            }
        }
    });

    excelTableContainer.addEventListener('click', (e) => {
        const addColBtn = e.target.closest('#excel-add-col-btn');
        if (addColBtn) {
            openAddFieldModal();
        }
    });
}

// Wire Excel Add Field modal options & close controls
document.getElementById('excel-add-field-close-btn')?.addEventListener('click', closeAddFieldModal);
document.getElementById('excel-add-field-cancel-btn')?.addEventListener('click', closeAddFieldModal);

document.getElementById('excel-add-field-list')?.addEventListener('click', (e) => {
    const btn = e.target.closest('.excel-add-field-option-btn');
    if (!btn) return;
    const fieldKey = btn.dataset.fieldKey;
    const fieldLabel = btn.dataset.fieldLabel || fieldKey;
    if (!fieldKey) return;

    const newColId = `col_${Date.now()}`;
    const newColHeader = fieldLabel.replace('*', '').trim();
    excelColumns.push({
        id: newColId,
        header: newColHeader,
        mappedField: fieldKey
    });
    excelWorkingRows.forEach(r => {
        r[newColId] = '';
    });
    closeAddFieldModal();
    rebuildAllExcelDataAndRender();
    showToast?.(`Column for "${newColHeader}" added to spreadsheet.`, 'success');
});

document.getElementById('cancel-upload-btn').addEventListener('click', () => {
    fileInput.value = '';
    excelParsedData = [];
    excelWorkingRows = [];
    excelColumns = [];
    isExcelEditMode = false;
    setExcelEditMode(false);
    const previewContainer = document.getElementById('excel-preview-table-container');
    if (previewContainer) {
        previewContainer.innerHTML = '';
        previewContainer.classList.add('hidden');
    }
    const dupContainer = document.getElementById('duplicate-policy-container');
    if (dupContainer) dupContainer.classList.add('hidden');
    const skipBtn = document.getElementById('skip-issues-upload-btn');
    if (skipBtn) skipBtn.classList.add('hidden');
    const startBtn = document.getElementById('start-upload-btn');
    const startBtnText = document.getElementById('start-upload-btn-text');
    if (startBtn) startBtn.disabled = false;
    if (startBtnText) startBtnText.textContent = 'Upload All';
    document.getElementById('upload-progress-bar').classList.add('hidden');
    document.getElementById('excel-drop-zone').classList.remove('hidden');
    document.getElementById('excel-preview-area').classList.add('hidden');
});

// Common execution function for bulk import / merge
async function executeBulkImport(datasetToUpload, mergePolicy) {
    if (!requirePermission('students.manage')) return;
    if (!datasetToUpload || !datasetToUpload.length) {
        return alert('No student records selected for upload.');
    }
    const selectedBulkClass = (document.getElementById('bulk-upload-class')?.value || '').toUpperCase().trim();
    if (!selectedBulkClass) return alert('Please select a target class.');

    const startBtn = document.getElementById('start-upload-btn');
    const skipBtn = document.getElementById('skip-issues-upload-btn');
    const cancelBtn = document.getElementById('cancel-upload-btn');
    const bar = document.getElementById('upload-progress-bar');
    const fill = document.getElementById('upload-progress-fill');
    const status = document.getElementById('upload-status-text');

    const statusModal = document.getElementById('excel-upload-status-modal');
    const progressView = document.getElementById('excel-upload-progress-view');
    const resultView = document.getElementById('excel-upload-result-view');
    const modalProgressFill = document.getElementById('excel-modal-progress-fill');
    const modalProgressText = document.getElementById('excel-modal-progress-text');
    const modalProgressPct = document.getElementById('excel-modal-progress-pct');
    const resultClass = document.getElementById('excel-result-class');
    const resultYear = document.getElementById('excel-result-year');
    const resultAdded = document.getElementById('excel-result-added');
    const resultMerged = document.getElementById('excel-result-merged');
    const resultSkipped = document.getElementById('excel-result-skipped');
    const okBtn = document.getElementById('excel-upload-ok-btn');

    startBtn.disabled = true;
    if (skipBtn) skipBtn.disabled = true;
    cancelBtn.disabled = true;
    bar.classList.remove('hidden');

    if (statusModal) {
        if (progressView) progressView.classList.remove('hidden');
        if (resultView) resultView.classList.add('hidden');
        if (modalProgressFill) modalProgressFill.style.width = '0%';
        if (modalProgressPct) modalProgressPct.textContent = '0%';
        if (modalProgressText) modalProgressText.textContent = `Processing 0 of ${datasetToUpload.length} students...`;
        statusModal.classList.remove('hidden');
        statusModal.classList.add('flex');
    }

    let addedCount = 0;
    let mergedCount = 0;
    let skippedCount = 0;
    const importedLookupRecords = [];

    try {
        const targetAcademicYear = getActiveAcademicYearLabel();

        for (let i = 0; i < datasetToUpload.length; i += 50) {
            const chunk = datasetToUpload.slice(i, i + 50);
            const batch = writeBatch(db);

            chunk.forEach((s) => {
                const effectiveClass = s.class || s.studentClass || selectedBulkClass || '';
                const studentStatus = s.status || 'Active';
                const customFieldsObj = (s.customFields && typeof s.customFields === 'object') ? { ...s.customFields } : {};
                const cleanPayload = {
                    name: s.name || '',
                    class: effectiveClass,
                    studentClass: effectiveClass,
                    status: studentStatus,
                    gender: s.gender || 'Male',
                    uid: s.uid || '',
                    father: s.father || '',
                    mother: s.mother || '',
                    mobile: s.mobile || '',
                    motherMobile: s.motherMobile || '',
                    adm: s.adm || '',
                    address: s.address || '',
                    dob: s.dob || '',
                    admDate: s.admDate || '',
                    adm_date: s.admDate || '',
                    adhaar: s.adhaar || '',
                    samasthaId: s.samasthaId || '',
                    photo: s.photo || '',
                    customFields: customFieldsObj,
                    academicYear: targetAcademicYear,
                    academicYears: {
                        [targetAcademicYear]: {
                            class: effectiveClass,
                            status: studentStatus,
                            updatedAt: new Date().toISOString()
                        }
                    },
                    profile: {
                        dob: s.dob || '',
                        address: s.address || '',
                        adhaar: s.adhaar || '',
                        admNo: s.adm || '',
                        admDate: s.admDate || '',
                        adm_date: s.admDate || '',
                        samasthaId: s.samasthaId || '',
                        photo: s.photo || '',
                        uid: s.uid || '',
                        father: s.father || '',
                        mother: s.mother || '',
                        mobile: s.mobile || '',
                        motherMobile: s.motherMobile || '',
                        status: studentStatus,
                        customFields: customFieldsObj
                    }
                };
                cleanPayload.phones = extractAllStudentPhones(cleanPayload, studentFieldSchema, normalizePhone);

                if (s.isDuplicate && s.existingMatch) {
                    if (mergePolicy === 'merge') {
                        // Merge fields into existing student document
                        const existingDocId = s.existingMatch.id;
                        const studentRef = doc(db, `${BASE_PATH}/students`, existingDocId);
                        
                        // Pick non-empty new values to merge into profile and root
                        const updateData = {};
                        ['name', 'gender', 'adm', 'dob', 'admDate', 'uid', 'father', 'mother', 'mobile', 'motherMobile', 'address', 'adhaar', 'status'].forEach(f => {
                            if (cleanPayload[f]) {
                                updateData[f] = cleanPayload[f];
                                updateData[`profile.${f}`] = cleanPayload[f];
                            }
                        });
                        const mergedCustom = {
                            ...getStudentCustomValuesMap(s.existingMatch),
                            ...Object.fromEntries(Object.entries(customFieldsObj).filter(([, v]) => String(v || '').trim() !== ''))
                        };
                        if (Object.keys(mergedCustom).length > 0) {
                            updateData.customFields = mergedCustom;
                            updateData['profile.customFields'] = mergedCustom;
                        }
                        const mergedStudentPreview = { ...s.existingMatch, ...updateData, customFields: mergedCustom };
                        updateData.phones = extractAllStudentPhones(mergedStudentPreview, studentFieldSchema, normalizePhone);
                        updateData.class = effectiveClass;
                        updateData.studentClass = effectiveClass;
                        updateData.academicYear = targetAcademicYear;
                        updateData[`academicYears.${targetAcademicYear}`] = {
                            class: effectiveClass,
                            status: studentStatus,
                            updatedAt: new Date().toISOString()
                        };

                        batch.set(studentRef, updateData, { merge: true });
                        batch.set(getEnrollmentRef(targetAcademicYear, existingDocId), buildEnrollmentPayload(existingDocId, { ...mergedStudentPreview, academicYear: targetAcademicYear }), { merge: true });
                        importedLookupRecords.push({ id: existingDocId, ...mergedStudentPreview });
                        mergedCount += 1;
                    } else {
                        // Skip existing
                        skippedCount += 1;
                    }
                } else {
                    // Create new student document
                    const studentRef = doc(collection(db, `${BASE_PATH}/students`));
                    batch.set(studentRef, cleanPayload);
                    batch.set(getEnrollmentRef(targetAcademicYear, studentRef.id), buildEnrollmentPayload(studentRef.id, cleanPayload), { merge: true });
                    importedLookupRecords.push({ id: studentRef.id, ...cleanPayload });
                    addedCount += 1;
                }
            });

            await batch.commit();
            const processedSoFar = Math.min(i + chunk.length, datasetToUpload.length);
            const pct = Math.round((processedSoFar / datasetToUpload.length) * 100);

            fill.style.width = `${pct}%`;
            status.textContent = `Processing ${processedSoFar} of ${datasetToUpload.length} students...`;

            if (modalProgressFill) modalProgressFill.style.width = `${pct}%`;
            if (modalProgressPct) modalProgressPct.textContent = `${pct}%`;
            if (modalProgressText) modalProgressText.textContent = `Processing ${processedSoFar} of ${datasetToUpload.length} students...`;
        }

        await syncActiveAcademicYearClasses([selectedBulkClass]);
        if (importedLookupRecords.length > 0) {
            await syncAllStudentsLookupIndex(importedLookupRecords);
        }
        scheduleAutoStatsSync(150);
        await logAuditEvent({
            category: 'student',
            action: 'student.import',
            entityType: 'student',
            message: `Bulk import processed ${datasetToUpload.length} students: ${addedCount} added, ${mergedCount} merged, ${skippedCount} skipped existing.`,
            metadata: { addedCount, mergedCount, skippedCount, targetClass: selectedBulkClass }
        });

        status.innerHTML = `<span class="text-emerald-600 font-bold">✔ Completed: ${addedCount} added, ${mergedCount} merged${skippedCount ? `, ${skippedCount} skipped` : ''}!</span>`;

        // Render Completion Modal
        if (statusModal && resultView) {
            if (progressView) progressView.classList.add('hidden');
            resultView.classList.remove('hidden');
            if (resultClass) resultClass.textContent = selectedBulkClass || '-';
            if (resultYear) resultYear.textContent = targetAcademicYear || '-';
            if (resultAdded) resultAdded.textContent = addedCount;
            if (resultMerged) resultMerged.textContent = mergedCount;
            if (resultSkipped) resultSkipped.textContent = skippedCount;

            if (okBtn) {
                okBtn.onclick = () => {
                    statusModal.classList.add('hidden');
                    statusModal.classList.remove('flex');
                    cancelBtn.disabled = false;
                    cancelBtn.click(); // Automatically closes the file preview & resets file input
                    showToast?.(`Successfully uploaded ${addedCount} students into Class ${selectedBulkClass}.`, 'success');
                };
            }
        } else {
            alert(`Bulk upload completed!\n\n• Newly Added: ${addedCount}\n• Merged / Updated: ${mergedCount}\n• Skipped (Duplicates): ${skippedCount}`);
            cancelBtn.disabled = false;
            cancelBtn.click();
        }
    } catch (err) {
        console.error("Bulk upload error:", err);
        if (statusModal) {
            statusModal.classList.add('hidden');
            statusModal.classList.remove('flex');
        }
        status.innerHTML = `<span class="text-rose-600 font-bold">Error uploading students: ${err.message}</span>`;
        alert("Upload error: " + err.message);
    } finally {
        startBtn.disabled = false;
        if (skipBtn) skipBtn.disabled = false;
        cancelBtn.disabled = false;
    }
}

// Upload All Click (Uploads all students with valid names, automatically omitting invalid optional fields)
document.getElementById('start-upload-btn').addEventListener('click', async () => {
    if (!excelParsedData || excelParsedData.length === 0) return;
    const validRows = excelParsedData.filter(s => !s.hasFatalError);
    const fatalRows = excelParsedData.filter(s => s.hasFatalError);
    const mergePolicy = document.querySelector('input[name="dup-action-policy"]:checked')?.value || 'skip';

    if (!validRows.length) {
        alert("Cannot upload: All rows are missing mandatory student names.");
        return;
    }

    const selectedBulkClass = (document.getElementById('bulk-upload-class')?.value || '').toUpperCase().trim();
    const totalOmitted = validRows.reduce((acc, s) => acc + (s.omittedFields?.length || 0), 0);

    let confirmMsg = `Upload all ${validRows.length} student(s) to Class ${selectedBulkClass}?`;
    if (totalOmitted > 0) {
        confirmMsg += `\n\n• Note: ${totalOmitted} invalid optional field(s) across these students will be omitted (saved as blank).`;
    }
    if (fatalRows.length > 0) {
        confirmMsg += `\n\n• Warning: ${fatalRows.length} row(s) missing mandatory student names will be skipped.`;
    }

    if (!confirm(confirmMsg)) return;
    await executeBulkImport(validRows, mergePolicy);
});

// Upload Valid Only Click (Uploads only completely valid students who have zero fatal errors and zero field errors)
document.getElementById('skip-issues-upload-btn')?.addEventListener('click', async () => {
    if (!excelParsedData || excelParsedData.length === 0) return;
    const completelyValidRows = excelParsedData.filter(s => !s.hasFatalError && (s.omittedFields?.length || 0) === 0);
    const invalidCount = excelParsedData.length - completelyValidRows.length;

    if (!completelyValidRows.length) {
        return alert('No completely valid student records without errors found.\n\nYou can use "Upload All" to upload students while skipping invalid optional fields.');
    }
    const mergePolicy = document.querySelector('input[name="dup-action-policy"]:checked')?.value || 'skip';
    const selectedBulkClass = (document.getElementById('bulk-upload-class')?.value || '').toUpperCase().trim();
    
    let confirmMsg = `Upload ${completelyValidRows.length} completely valid student(s) to Class ${selectedBulkClass}?`;
    if (invalidCount > 0) {
        confirmMsg += `\n\n• Note: ${invalidCount} record(s) containing errors or missing data will be skipped.`;
    }

    if (!confirm(confirmMsg)) return;
    await executeBulkImport(completelyValidRows, mergePolicy);
});

