const canUserViewAlumni = () => {
    if (!isStaffAdminSession) return true;
    if (staffAdminRecord?.canAccessAdmin === true || staffAdminRecord?.actLikeSuperAdmin === true || currentAdminRole === 'super_admin') return true;
    const duty = Array.isArray(staffAdminRecord?.dutyClasses) ? staffAdminRecord.dutyClasses : [];
    return duty.some(c => String(c).trim().toUpperCase() === 'ALUMNI');
};

const getStudentInitials = (name = '') => {
    const parts = String(name || '').trim().split(/\s+/).filter(Boolean);
    if (parts.length === 0) return 'ST';
    if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
    return (parts[0][0] + parts[1][0]).toUpperCase();
};

const populateManageClassDropdown = (selectedYear = getActiveAcademicYearLabel()) => {
    const filterManage = document.getElementById('filter-manage-class');
    if (!filterManage) return;
    const prevVal = filterManage.value;
    const yearClasses = getClassesForYear(selectedYear).filter(c => {
        const u = String(c).trim().toUpperCase();
        return u && u !== 'ALUMNI' && u !== 'GRADUATED';
    });

    let optionsHtml = `<option value="">-- Select Class --</option><option value="all">All Classes</option>`;
    if (yearClasses.length > 0) {
        yearClasses.forEach(cls => {
            const raw = String(cls).trim();
            const label = raw.toLowerCase().startsWith('class') ? raw : `Class: ${raw}`;
            optionsHtml += `<option value="${escapeHtml(raw)}">${escapeHtml(label)}</option>`;
        });
    }

    filterManage.innerHTML = optionsHtml;
    if (prevVal === 'all' || (prevVal && filterManage.querySelector(`option[value="${CSS.escape(prevVal)}"]`))) {
        filterManage.value = prevVal;
    } else {
        filterManage.value = '';
    }
    syncSmartSelectDisplay(filterManage);
};

// --- 3. MANAGE STUDENTS ---
const populateClassDropdowns = () => {
    classes = getClassesForActiveYear();
    const opts = classes.map(c => {
        const raw = String(c).trim();
        const label = raw.toLowerCase().startsWith('class') ? raw : `Class: ${raw}`;
        return `<option value="${escapeHtml(raw)}">${escapeHtml(label)}</option>`;
    }).join('');
    const classOptsWithAlumni = opts + `<option value="ALUMNI">Alumni</option>`;
    const dataList = document.getElementById('class-suggestions');
    if (dataList) dataList.innerHTML = opts;

    const addClassSelect = document.getElementById('add-stu-class');
    if (addClassSelect) {
        const prevAddVal = addClassSelect.value;
        addClassSelect.innerHTML = `<option value="">-- Select Class --</option>` + classOptsWithAlumni;
        if (prevAddVal && (classes.includes(prevAddVal) || prevAddVal === 'ALUMNI')) {
            addClassSelect.value = prevAddVal;
        }
        syncSmartSelectDisplay(addClassSelect);
    }

    const editClassSelect = document.getElementById('e-stu-class');
    if (editClassSelect) {
        const prevEditVal = editClassSelect.value;
        editClassSelect.innerHTML = `<option value="">-- Select Class --</option>` + classOptsWithAlumni;
        if (prevEditVal && (classes.includes(prevEditVal) || prevEditVal === 'ALUMNI')) {
            editClassSelect.value = prevEditVal;
        }
        syncSmartSelectDisplay(editClassSelect);
    }

    const yearOptions = (academicYears || []).map(y => {
        const yLbl = typeof y === 'string' ? y : (y?.label || y?.year || '');
        return yLbl ? `<option value="${escapeHtml(yLbl)}">${escapeHtml(yLbl)}</option>` : '';
    }).filter(Boolean).join('');
    const addPassedOut = document.getElementById('add-stu-passed-out-year');
    if (addPassedOut) {
        const prev = addPassedOut.value;
        addPassedOut.innerHTML = yearOptions;
        if (prev) addPassedOut.value = prev;
        else if (activeAcademicYear) addPassedOut.value = activeAcademicYear;
    }
    const editPassedOut = document.getElementById('e-stu-passed-out-year');
    if (editPassedOut) {
        const prev = editPassedOut.value;
        editPassedOut.innerHTML = yearOptions;
        if (prev) editPassedOut.value = prev;
        else if (activeAcademicYear) editPassedOut.value = activeAcademicYear;
    }

    const currentYearVal = document.getElementById('filter-manage-academic-year')?.value || getActiveAcademicYearLabel();
    populateManageClassDropdown(currentYearVal);

    const filterConc = document.getElementById('filter-conc-class'); const prevConcVal = filterConc.value;
    filterConc.innerHTML = `<option value="all">All Classes</option>` + opts; if(classes.includes(prevConcVal) || prevConcVal === 'all') filterConc.value = prevConcVal;

    const activeConcClassFilter = document.getElementById('active-conc-class-filter');
    if (activeConcClassFilter) {
        const prevActVal = activeConcClassFilter.value;
        activeConcClassFilter.innerHTML = `<option value="all">All Classes</option>` + opts;
        if (prevActVal === 'all' || classes.includes(prevActVal)) activeConcClassFilter.value = prevActVal;
    }
    const bulkClassSel = document.getElementById('bulk-upload-class');
    if (bulkClassSel) {
        const prevBulkClass = bulkClassSel.value;
        bulkClassSel.innerHTML = `<option value="">-- Select Class --</option>` + opts;
        if (classes.includes(prevBulkClass)) bulkClassSel.value = prevBulkClass;
        syncSmartSelectDisplay(bulkClassSel);
    }
    if (typeof renderStaffClassCheckboxes === 'function') {
        const checkedValues = Array.from(document.querySelectorAll('#st-duty-classes-grid .staff-class-checkbox:checked')).map(cb => cb.value);
        renderStaffClassCheckboxes('st', checkedValues);
    }
    syncSmartSelectDisplay(document);
};

const populateManageAcademicYearDropdown = (forceActive = false) => {
    const yearSelect = document.getElementById('filter-manage-academic-year');
    if (!yearSelect) return;
    if (forceActive) yearSelect.dataset.userChangedYear = 'false';
    const currentSelected = forceActive ? getActiveAcademicYearLabel() : (yearSelect.value || getActiveAcademicYearLabel());
    populateAcademicYearSelect(yearSelect, academicYears, getActiveAcademicYearLabel(), {
        selectedValue: currentSelected,
        preferCurrentUnlessUserChanged: !forceActive
    });
};

const openStudentHistoryModal = (studentId) => {
    const student = rawStudents.find(s => s.id === studentId);
    if (!student) return alert('Student not found.');
    
    const summaryContainer = document.getElementById('student-history-profile-summary');
    const timelineContainer = document.getElementById('student-history-timeline-container');
    const popup = document.getElementById('student-history-popup');
    if (!summaryContainer || !timelineContainer || !popup) return;

    const stuPhoto = student.photo || student.profile?.photo || '';
    const prof = student.profile || {};
    const currentClass = student.class || student.studentClass || prof.class || '--';
    const status = normalizeStudentStatus(student.status || prof.status);

    summaryContainer.innerHTML = `
        <div class="w-16 h-16 rounded-full overflow-hidden bg-white border-2 border-slate-200 flex items-center justify-center shrink-0 shadow-sm">
            ${stuPhoto ? `<img src="${stuPhoto}" class="w-full h-full object-cover">` : `<i class="fas fa-user text-slate-400 text-2xl"></i>`}
        </div>
        <div class="flex-1 text-center sm:text-left">
            <div class="flex flex-wrap items-center justify-center sm:justify-start gap-2">
                <h4 class="text-lg font-black text-gray-900">${escapeHtml(student.name || '--')}</h4>
                <span class="px-2.5 py-0.5 rounded-full text-xs font-bold border ${getStudentStatusBadgeClass(status)}">${escapeHtml(status)}</span>
            </div>
            <div class="grid grid-cols-2 sm:grid-cols-4 gap-2 text-xs text-gray-600 mt-2">
                <div><span class="text-gray-400 block font-bold">Adm. No:</span> <span class="font-mono font-bold">${escapeHtml(student.adm || prof.admNo || '-')}</span></div>
                <div><span class="text-gray-400 block font-bold">Current Class:</span> <span class="font-bold text-indigo-700">${escapeHtml(currentClass)}</span></div>
                <div><span class="text-gray-400 block font-bold">Gender:</span> <span>${escapeHtml(student.gender || prof.gender || '-')}</span></div>
                <div><span class="text-gray-400 block font-bold">Mobile:</span> <span>${escapeHtml(student.mobile || prof.mobile || '-')}</span></div>
            </div>
        </div>
    `;

    const historyMap = (student.academicYears && typeof student.academicYears === 'object') ? { ...student.academicYears } : {};

    // Supplement history from examResultsCache if there are results for past years not yet in historyMap
    if (Array.isArray(examResultsCache)) {
        examResultsCache.forEach((row) => {
            if (row.studentId === studentId && row.academicYear) {
                const yr = String(row.academicYear).trim();
                if (!historyMap[yr]) {
                    historyMap[yr] = {
                        class: row.classLabel || '--',
                        status: 'Active',
                        decision: 'Appeared in Exams',
                        updatedAt: row.updatedAt || null
                    };
                }
            }
        });
    }

    // Supplement if student has promotedFrom and graduatedYear
    if (student.promotedFrom && student.graduatedYear && !historyMap[student.graduatedYear]) {
        historyMap[student.graduatedYear] = {
            class: student.promotedFrom,
            status: 'Active',
            decision: 'graduated',
            updatedAt: student.promotedAt || null
        };
    }

    // Supplement current active session if not present
    const masterYear = student.academicYear || getActiveAcademicYearLabel();
    if (masterYear && !historyMap[masterYear]) {
        historyMap[masterYear] = {
            class: currentClass,
            status: status,
            decision: 'Enrolled',
            updatedAt: student.updatedAt || null
        };
    }

    const recordedYears = Object.keys(historyMap);
    const entries = recordedYears.map(yearLabel => {
        const entry = historyMap[yearLabel] || {};
        return {
            yearLabel,
            class: entry.class || currentClass,
            status: entry.status || 'Active',
            decision: entry.decision || null,
            updatedAt: entry.updatedAt || null
        };
    });

    entries.sort((a, b) => b.yearLabel.localeCompare(a.yearLabel, undefined, { numeric: true }));

    timelineContainer.innerHTML = entries.map((entry) => {
        const isCurrent = entry.yearLabel === getActiveAcademicYearLabel();
        const entryStatus = normalizeStudentStatus(entry.status);
        const formattedDate = entry.updatedAt ? new Date(entry.updatedAt).toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' }) : 'Recorded';

        return `
            <div class="p-3.5 rounded-xl border ${isCurrent ? 'border-indigo-200 bg-indigo-50/50' : 'border-gray-200 bg-white'} shadow-2xs transition">
                <div class="flex items-center justify-between flex-wrap gap-2">
                    <div class="flex items-center gap-2">
                        <span class="text-sm font-black text-gray-900">${escapeHtml(entry.yearLabel)}</span>
                        ${isCurrent ? '<span class="px-2 py-0.5 rounded text-[10px] font-bold bg-indigo-100 text-indigo-800 border border-indigo-200">Current Session</span>' : '<span class="px-2 py-0.5 rounded text-[10px] font-bold bg-gray-100 text-gray-600">Past Session</span>'}
                    </div>
                    <div class="text-[11px] text-gray-400 font-medium">${escapeHtml(formattedDate)}</div>
                </div>
                <div class="grid grid-cols-2 sm:grid-cols-3 gap-2 mt-2 pt-2 border-t border-gray-100 text-xs">
                    <div>
                        <span class="text-gray-500 block text-[10px] font-bold uppercase">Class in that year:</span>
                        <span class="font-extrabold text-gray-900 text-sm">${escapeHtml(entry.class || '--')}</span>
                    </div>
                    <div>
                        <span class="text-gray-500 block text-[10px] font-bold uppercase">Year Status:</span>
                        <span class="inline-flex px-2 py-0.5 rounded-full text-xs font-bold border mt-0.5 ${getStudentStatusBadgeClass(entryStatus)}">${escapeHtml(entryStatus)}</span>
                    </div>
                    <div>
                        <span class="text-gray-500 block text-[10px] font-bold uppercase">Progression:</span>
                        <span class="text-xs font-semibold text-gray-700">${entry.decision ? escapeHtml(entry.decision.toUpperCase()) : 'Enrolled'}</span>
                    </div>
                </div>
            </div>
        `;
    }).join('');

    popup.classList.remove('hidden');
    popup.classList.add('flex');
};

