const downloadStudentPhotoAsPng = (photoSource, studentName) => {
    if (!photoSource) {
        alert('No photo available to download.');
        return;
    }

    const triggerDownload = (url) => {
        const cleanName = String(studentName || 'student_photo')
            .trim()
            .replace(/[/\\?%*:|"<>]/g, '_')
            .replace(/\s+/g, '_');
        const filename = `${cleanName}.png`;
        const link = document.createElement('a');
        link.href = url;
        link.download = filename;
        document.body.appendChild(link);
        link.click();
        link.remove();
    };

    const img = new Image();
    img.crossOrigin = 'anonymous';

    img.onload = () => {
        try {
            const canvas = document.createElement('canvas');
            const targetWidth = img.naturalWidth || img.width || 400;
            const targetHeight = img.naturalHeight || img.height || 400;
            canvas.width = targetWidth;
            canvas.height = targetHeight;
            const ctx = canvas.getContext('2d');
            if (!ctx) {
                triggerDownload(photoSource);
                return;
            }

            // Draw at original maximum native resolution
            ctx.drawImage(img, 0, 0, targetWidth, targetHeight);

            if (canvas.toBlob) {
                canvas.toBlob((blob) => {
                    if (blob) {
                        const blobUrl = URL.createObjectURL(blob);
                        triggerDownload(blobUrl);
                        setTimeout(() => URL.revokeObjectURL(blobUrl), 10000);
                    } else {
                        const dataUrl = canvas.toDataURL('image/png', 1.0);
                        triggerDownload(dataUrl);
                    }
                }, 'image/png');
            } else {
                const dataUrl = canvas.toDataURL('image/png', 1.0);
                triggerDownload(dataUrl);
            }
        } catch (err) {
            console.warn('Canvas conversion notice, falling back to direct download:', err);
            triggerDownload(photoSource);
        }
    };

    img.onerror = (e) => {
        console.warn('Image load error, falling back to direct download:', e);
        triggerDownload(photoSource);
    };

    img.src = photoSource;
};

let studentManagePage = 1;
let studentManagePageSize = 25;

const updateStudentPaginationUI = (totalCount = 0, startIdx = 0, endIdx = 0, totalPages = 1) => {
    const topBar = document.getElementById('student-pagination-top');
    const bottomBar = document.getElementById('student-pagination-bottom');
    if (!topBar || !bottomBar) return;

    if (totalCount === 0) {
        topBar.classList.add('hidden');
        bottomBar.classList.add('hidden');
        return;
    }

    topBar.classList.remove('hidden');
    bottomBar.classList.remove('hidden');

    const topInfo = document.getElementById('student-pagination-info-top');
    const bottomInfo = document.getElementById('student-pagination-info-bottom');
    const topPageNum = document.getElementById('student-page-number-display');
    const bottomPageNum = document.getElementById('student-page-number-display-bottom');
    const sizeSelect = document.getElementById('student-page-size-select');

    if (sizeSelect && sizeSelect.value !== String(studentManagePageSize)) {
        sizeSelect.value = String(studentManagePageSize);
    }

    const rangeStrTop = `Showing ${totalCount ? startIdx + 1 : 0}–${endIdx} of ${totalCount}`;
    const rangeStrBottom = `Showing rows ${totalCount ? startIdx + 1 : 0} to ${endIdx} of ${totalCount} students`;
    const pageStr = `Page ${studentManagePage} / ${totalPages || 1}`;

    if (topInfo) topInfo.textContent = rangeStrTop;
    if (bottomInfo) bottomInfo.textContent = rangeStrBottom;
    if (topPageNum) topPageNum.textContent = pageStr;
    if (bottomPageNum) bottomPageNum.textContent = pageStr;

    const isPrevDisabled = studentManagePage <= 1;
    const isNextDisabled = studentManagePage >= totalPages;

    const prevTop = document.getElementById('student-prev-page-btn');
    const prevBottom = document.getElementById('student-prev-page-btn-bottom');
    const nextTop = document.getElementById('student-next-page-btn');
    const nextBottom = document.getElementById('student-next-page-btn-bottom');

    if (prevTop) prevTop.disabled = isPrevDisabled;
    if (prevBottom) prevBottom.disabled = isPrevDisabled;
    if (nextTop) nextTop.disabled = isNextDisabled;
    if (nextBottom) nextBottom.disabled = isNextDisabled;
};

const matchesStudentSearch = (s, rawTerm = '') => {
    if (!s) return false;
    const term = String(rawTerm || '').toLowerCase().trim();
    if (!term) return true;

    // Direct text / string matching
    if (s.name && s.name.toLowerCase().includes(term)) return true;
    if (s.adm && String(s.adm).toLowerCase().includes(term)) return true;
    if (s.uid && String(s.uid).toLowerCase().includes(term)) return true;
    if (s.father && s.father.toLowerCase().includes(term)) return true;
    if (s.mother && s.mother.toLowerCase().includes(term)) return true;
    if (s.guardian && s.guardian.toLowerCase().includes(term)) return true;

    // Digits-only phone / aadhaar matching if term has digits
    const digitsInTerm = term.replace(/\D/g, '');
    if (digitsInTerm.length >= 3) {
        const studentIdentifiers = [
            s.mobile,
            s.motherMobile,
            s.phone,
            s.adhaar,
            s.aadhaar,
            s.profile?.mobile,
            s.profile?.motherMobile,
            s.profile?.phone,
            s.profile?.adhaar,
            s.profile?.aadhaar
        ].filter(Boolean).map(val => String(val).replace(/\D/g, ''));

        if (studentIdentifiers.some(digits => digits.includes(digitsInTerm))) {
            return true;
        }
    }

    return false;
};

const renderStudentList = () => {
    const selectedYear = document.getElementById('filter-manage-academic-year')?.value || getActiveAcademicYearLabel();
    const isActiveYear = selectedYear === getActiveAcademicYearLabel();
    const isHistoricalView = isHistoricalAcademicYear(selectedYear, getActiveAcademicYearLabel());

    const fCls = document.getElementById('filter-manage-class')?.value || '';
    const fGen = document.getElementById('filter-manage-gender')?.value || 'all';
    const fStatus = document.getElementById('filter-manage-status')?.value || 'all';
    const sortType = document.getElementById('sort-manage-students')?.value || 'name-asc';
    const sTerm = document.getElementById('search-student-input')?.value?.toLowerCase().trim() || '';
    const cont = document.getElementById('student-list-container');
    const emptyState = document.getElementById('student-list-empty-state');
    const archiveBanner = document.getElementById('historical-archive-banner');
    const archiveYearLabel = document.getElementById('historical-archive-year-label');
    const yearBadge = document.getElementById('manage-students-year-badge');

    if (yearBadge) {
        yearBadge.textContent = `Academic Year: ${selectedYear}${isActiveYear ? ' (Current)' : ''}`;
        yearBadge.className = `text-xs font-bold uppercase tracking-widest mt-1 ${isActiveYear ? 'text-indigo-600' : 'text-slate-600'}`;
    }

    if (archiveBanner) {
        if (isHistoricalView) {
            archiveBanner.classList.remove('hidden');
            if (archiveYearLabel) archiveYearLabel.textContent = selectedYear;
        } else {
            archiveBanner.classList.add('hidden');
        }
    }

    if (!fCls && !sTerm) {
        if (cont) {
            cont.innerHTML = '';
            cont.classList.add('hidden');
        }
        if (emptyState) emptyState.classList.remove('hidden');
        updateStudentPaginationUI(0, 0, 0, 1);
        return;
    }

    if (emptyState) emptyState.classList.add('hidden');
    if (cont) cont.classList.remove('hidden');

    const yearStudents = getStudentsForYear(selectedYear);

    const fil = yearStudents.filter(s => {
        const isAlum = normalizeStudentStatus(s.status) === 'Alumni' || s.isAlumni === true || String(s.class || '').toUpperCase() === 'ALUMNI';
        if (isAlum) return false; // Manage Students strictly displays active enrolled students

        let match = true;
        if (fCls && fCls !== 'all') match = match && s.class === fCls;
        if (fGen !== 'all') match = match && s.gender === fGen;
        if (fStatus !== 'all') {
            match = match && normalizeStudentStatus(s.status) === fStatus;
        } else {
            match = match && normalizeStudentStatus(s.status) !== 'Discontinued';
        }
        if (sTerm) match = match && matchesStudentSearch(s, sTerm);
        return match;
    });

    if(fil.length === 0) {
        if (cont) cont.innerHTML = '<p class="text-gray-500 p-4 text-center font-medium">No students found.</p>';
        updateStudentPaginationUI(0, 0, 0, 1);
        return;
    }

    const compareByAdmission = (a, b) => {
        const admA = a.adm ? a.adm.toString().trim() : ""; const admB = b.adm ? b.adm.toString().trim() : "";
        if (admA === "" && admB === "") return (a.name || '').localeCompare(b.name || '');
        if (admA === "") return 1; if (admB === "") return -1;
        const numA = parseFloat(admA); const numB = parseFloat(admB);
        if (!isNaN(numA) && !isNaN(numB) && numA !== numB) return numA - numB;
        return admA.localeCompare(admB, undefined, {numeric: true});
    };
    if (sortType === 'male-first') {
        fil.sort((a, b) => {
            const genderOrder = (a.gender === 'Male' ? 0 : 1) - (b.gender === 'Male' ? 0 : 1);
            if (genderOrder !== 0) return genderOrder;
            return compareByAdmission(a, b);
        });
    } else if (sortType === 'name-asc') {
        fil.sort((a, b) => (a.name || '').localeCompare(b.name || ''));
    } else {
        fil.sort(compareByAdmission);
    }

    const totalCount = fil.length;
    const effectivePageSize = studentManagePageSize > 0 ? studentManagePageSize : totalCount;
    const totalPages = effectivePageSize > 0 ? Math.ceil(totalCount / effectivePageSize) : 1;

    if (studentManagePage > totalPages) studentManagePage = totalPages || 1;
    if (studentManagePage < 1) studentManagePage = 1;

    const startIdx = studentManagePageSize > 0 ? (studentManagePage - 1) * studentManagePageSize : 0;
    const endIdx = studentManagePageSize > 0 ? Math.min(startIdx + studentManagePageSize, totalCount) : totalCount;
    const pagedStudents = studentManagePageSize > 0 ? fil.slice(startIdx, endIdx) : fil;

    updateStudentPaginationUI(totalCount, startIdx, endIdx, totalPages);

    let html = `
    <table class="w-full text-sm text-left whitespace-nowrap">
        <thead class="table-header">
            <tr><th class="p-3 w-16 text-center">Sl. No</th><th class="p-3 w-16">Photo</th><th class="p-3">Adm.No</th><th class="p-3">Name</th><th class="p-3">Class, Gender & Status</th><th class="p-3">Mobile</th><th class="p-3 text-right">Actions</th></tr>
        </thead><tbody class="divide-y divide-gray-200">`;

    pagedStudents.forEach((s, i) => {
        const rowNumber = startIdx + i + 1;
        const status = normalizeStudentStatus(s.status);
        const stuPhoto = s.photo || s.profile?.photo || '';
        let actionButtons = '';

        if (!isActiveYear) {
            actionButtons = `
                <button type="button" class="view-student-details-btn bg-blue-50 text-blue-700 hover:bg-blue-100 px-2.5 py-1.5 rounded-md text-xs font-bold transition cursor-pointer" data-student-id="${s.id}" title="View Student Full Details"><i class="fas fa-id-card"></i></button>
            `;
        } else {
            actionButtons = `
                <button type="button" class="view-student-details-btn bg-blue-50 text-blue-700 hover:bg-blue-100 px-2.5 py-1.5 rounded-md mr-1.5 text-xs font-bold transition cursor-pointer" data-student-id="${s.id}" title="View Student Full Details"><i class="fas fa-id-card"></i></button>
                <button class="edit-student-btn bg-blue-50 text-blue-600 hover:bg-blue-100 px-3 py-1.5 rounded-md mr-1.5 text-xs font-bold transition cursor-pointer" data-id="${s.id}"><i class="fas fa-edit"></i> Edit</button>
                <button class="delete-student-btn bg-red-50 text-red-600 hover:bg-red-100 px-2.5 py-1.5 rounded-md text-xs font-bold transition cursor-pointer" data-id="${s.id}"><i class="fas fa-trash"></i></button>
            `;
        }

        html += `
        <tr class="hover:bg-gray-50 bg-white">
            <td class="p-3 text-center font-bold text-gray-400">${rowNumber}</td>
            <td class="p-3">
                <div class="relative inline-block">
                    <div class="w-10 h-10 rounded-full overflow-hidden bg-slate-100 border border-slate-200 flex items-center justify-center shrink-0 shadow-inner">
                        ${stuPhoto ? `<img src="${escapeHtml(stuPhoto)}" class="w-full h-full object-cover" alt="${escapeHtml(s.name || 'Student')}" onerror="this.onerror=null; this.classList.add('hidden'); this.nextElementSibling?.classList.remove('hidden');"><i class="fas fa-user text-slate-400 text-sm hidden"></i>` : `<i class="fas fa-user text-slate-400 text-sm"></i>`}
                    </div>
                    ${stuPhoto ? `
                    <button type="button" class="download-student-photo-btn absolute -bottom-1 -left-1 w-5 h-5 bg-blue-600 hover:bg-blue-700 active:scale-95 text-white rounded-full flex items-center justify-center shadow-xs transition cursor-pointer text-[9px] border-2 border-white" data-student-id="${s.id}" data-name="${escapeHtml(s.name || 'student')}" title="Download Photo (PNG)">
                        <i class="fas fa-download text-[7.5px] pointer-events-none"></i>
                    </button>
                    ` : ''}
                </div>
            </td>
            <td class="p-3 font-mono text-gray-500 font-medium">${escapeHtml(s.adm || '-')}</td>
            <td class="p-3 font-bold text-gray-900">
                <button type="button" class="view-student-details-btn hover:text-blue-600 hover:underline cursor-pointer text-left inline-flex items-center gap-1.5" data-student-id="${s.id}" title="Click to view full student details">
                    <span>${escapeHtml(s.name || '-')}</span>
                </button>
            </td>
            <td class="p-3 text-gray-600">
                <div>${escapeHtml(s.class || '--')} (${escapeHtml(s.gender || '--')})</div>
                <div class="mt-1 flex flex-wrap items-center gap-1">
                    <span class="inline-flex px-2 py-0.5 rounded-full border text-xs font-bold ${getStudentStatusBadgeClass(status)}">${escapeHtml(status)}</span>
                    ${(status === 'Alumni' || s.isAlumni || s.passedOutYear) ? `<span class="inline-flex items-center px-1.5 py-0.5 rounded-md border border-indigo-200 bg-indigo-50 text-[10px] font-bold text-indigo-700" title="Graduation / Pass-out Year"><i class="fas fa-graduation-cap mr-1"></i>${escapeHtml(s.passedOutYear || s.graduatedYear || 'Alumni')}</span>` : ''}
                </div>
            </td>
            <td class="p-3 text-gray-500">${escapeHtml(s.mobile || '-')}</td>
            <td class="p-3 text-right">
                ${actionButtons}
            </td>
        </tr>`;
    });
    if (cont) cont.innerHTML = html + `</tbody></table>`;
};
