// --- 6. FEE CONCESSIONS ---
const renderActiveConcessionsList = () => {
    const actCont = document.getElementById('active-concessions-list');
    const badgeCount = document.getElementById('active-conc-count-badge');
    const statusText = document.getElementById('active-conc-filter-status');
    if (!actCont) return;

    const sTerm = (document.getElementById('active-conc-search')?.value || '').trim().toLowerCase();
    const fCls = document.getElementById('active-conc-class-filter')?.value || 'all';

    const withConc = students.filter(s => s.concessionFee !== undefined && s.concessionFee !== null && s.concessionFee !== '');

    if (badgeCount) {
        badgeCount.textContent = String(withConc.length);
    }

    const filtered = withConc.filter(s => {
        let match = true;
        if (fCls && fCls !== 'all') {
            match = match && s.class === fCls;
        }
        if (sTerm) {
            const nameMatch = (s.name || '').toLowerCase().includes(sTerm);
            const admMatch = (s.adm || '').toLowerCase().includes(sTerm);
            const phoneMatch = (s.phone || '').toLowerCase().includes(sTerm) || (s.parentPhone || '').toLowerCase().includes(sTerm);
            const fatherMatch = (s.fatherName || '').toLowerCase().includes(sTerm);
            match = match && (nameMatch || admMatch || phoneMatch || fatherMatch);
        }
        return match;
    });

    if (statusText) {
        if (fCls !== 'all' || sTerm) {
            statusText.textContent = `Showing ${filtered.length} of ${withConc.length}`;
        } else {
            statusText.textContent = `Showing All (${withConc.length})`;
        }
    }

    if (filtered.length === 0) {
        actCont.innerHTML = `
            <tr>
                <td colspan="6" class="text-center py-8 px-4 text-slate-400 text-xs">
                    <i class="fas fa-search text-emerald-300 text-lg mb-1.5 block"></i>
                    ${withConc.length === 0 ? 'No active fee concessions registered yet.' : 'No concessions match the current search or class filter.'}
                </td>
            </tr>
        `;
        return;
    }

    actCont.innerHTML = filtered.map((s, idx) => {
        const studentName = escapeHtml(s.name || '-');
        const studentClass = escapeHtml(s.class || '--');
        const admNo = escapeHtml(s.adm || '-');
        const concessionAmt = escapeHtml(String(s.concessionFee));
        const father = s.fatherName ? escapeHtml(s.fatherName) : '';

        return `
            <tr class="hover:bg-emerald-50/40 transition-colors">
                <td class="py-2.5 px-3 text-center text-slate-400 font-semibold text-xs">${idx + 1}</td>
                <td class="py-2.5 px-3">
                    <button type="button" class="font-bold text-slate-800 text-xs hover:text-emerald-700 hover:underline cursor-pointer view-student-details-btn text-left inline-flex items-center gap-1.5" data-student-id="${s.id}" title="Click to view full student details">
                        <span>${studentName}</span>
                        <i class="fas fa-external-link-alt text-[9px] text-slate-400"></i>
                    </button>
                    ${father ? `<div class="text-[10px] text-slate-400 flex items-center gap-1 mt-0.5"><i class="fas fa-user-shield text-[9px]"></i> ${father}</div>` : ''}
                </td>
                <td class="py-2.5 px-3 text-center">
                    <span class="inline-flex items-center px-2 py-0.5 rounded-md bg-blue-50 text-blue-700 text-[11px] font-bold border border-blue-200/80">
                        Class ${studentClass}
                    </span>
                </td>
                <td class="py-2.5 px-3 text-center">
                    <span class="inline-flex items-center px-2 py-0.5 rounded-md bg-slate-100 text-slate-700 text-[11px] font-semibold border border-slate-200/70">
                        ${admNo}
                    </span>
                </td>
                <td class="py-2.5 px-3 text-right">
                    <span class="inline-flex items-center font-extrabold text-xs text-emerald-800 bg-emerald-50 border border-emerald-200 px-2 py-0.5 rounded-md shadow-2xs">
                        ₹${concessionAmt}
                    </span>
                </td>
                <td class="py-2.5 px-3 text-center">
                    <div class="inline-flex items-center justify-center gap-1">
                        <button type="button" class="bg-blue-50 hover:bg-blue-100 text-blue-700 p-1.5 rounded-md text-xs transition concession-open-btn" data-id="${s.id}" title="Edit Concession">
                            <i class="fas fa-edit"></i>
                        </button>
                        <button type="button" class="bg-rose-50 hover:bg-rose-100 text-rose-700 p-1.5 rounded-md text-xs transition concession-delete-btn" data-id="${s.id}" title="Remove Concession">
                            <i class="fas fa-trash-alt"></i>
                        </button>
                    </div>
                </td>
            </tr>
        `;
    }).join('');
};

const renderConcessionsList = () => {
    const fCls = document.getElementById('filter-conc-class')?.value || '';
    const sTerm = (document.getElementById('search-conc-input')?.value || '').trim().toLowerCase();
    const cont = document.getElementById('conc-list-container');
    const emptyState = document.getElementById('conc-list-empty');

    renderActiveConcessionsList();

    if (!cont || !emptyState) return;

    if (!fCls && !sTerm) {
        emptyState.classList.remove('hidden');
        cont.classList.add('hidden');
        return;
    }
    emptyState.classList.add('hidden');
    cont.classList.remove('hidden');

    const fil = students.filter(s => {
        let match = true;
        if (fCls && fCls !== 'all') match = match && s.class === fCls;
        if (sTerm) match = match && ((s.name || '').toLowerCase().includes(sTerm) || (s.adm && String(s.adm).toLowerCase().includes(sTerm)));
        return match;
    });

    if (fil.length === 0) {
        cont.innerHTML = '<p class="text-xs text-slate-500 py-4 text-center">No matching students found.</p>';
        return;
    }

    cont.innerHTML = fil.map(s => {
        const hasConc = s.concessionFee !== undefined && s.concessionFee !== null && s.concessionFee !== '';
        return `
            <div class="p-2.5 bg-white border border-slate-200 rounded-lg shadow-2xs hover:border-blue-200 transition flex items-center justify-between gap-2">
                <div class="min-w-0 flex-1">
                    <button type="button" class="font-bold text-xs text-slate-800 break-words leading-tight hover:text-blue-600 hover:underline cursor-pointer view-student-details-btn text-left inline-flex items-center gap-1.5" data-student-id="${s.id}" title="Click to view full student details">
                        <span>${escapeHtml(s.name || '-')}</span>
                        <i class="fas fa-external-link-alt text-[9px] text-slate-400"></i>
                    </button>
                    <div class="flex items-center gap-1.5 text-[11px] text-slate-500 mt-1">
                        <span class="font-medium text-slate-700 bg-slate-100 px-1.5 py-0.5 rounded">Class ${escapeHtml(s.class || '--')}</span>
                        <span>•</span>
                        <span>Adm: ${escapeHtml(s.adm || '-')}</span>
                    </div>
                </div>
                <div class="flex items-center gap-1.5 shrink-0">
                    ${hasConc ? `<span class="bg-emerald-50 text-emerald-800 text-[11px] font-bold px-2 py-0.5 rounded border border-emerald-200">₹${escapeHtml(String(s.concessionFee))}</span>` : ''}
                    <button type="button" class="bg-blue-50 hover:bg-blue-100 text-blue-700 font-bold px-2.5 py-1 rounded-md text-xs transition concession-open-btn" data-id="${s.id}">
                        ${hasConc ? 'Edit' : 'Assign'}
                    </button>
                    ${hasConc ? `<button type="button" class="bg-rose-50 hover:bg-rose-100 text-rose-700 font-bold px-2 py-1 rounded-md text-xs transition concession-delete-btn" data-id="${s.id}"><i class="fas fa-trash-alt text-[10px]"></i></button>` : ''}
                </div>
            </div>
        `;
    }).join('');
};

document.getElementById('filter-conc-class')?.addEventListener('change', renderConcessionsList);
document.getElementById('search-conc-input')?.addEventListener('input', renderConcessionsList);
document.getElementById('active-conc-search')?.addEventListener('input', renderActiveConcessionsList);
document.getElementById('active-conc-class-filter')?.addEventListener('change', renderActiveConcessionsList);

document.getElementById('fee-concessions-page')?.addEventListener('click', (e) => {
    const btn = e.target.closest('.concession-open-btn');
    const delBtn = e.target.closest('.concession-delete-btn');
    if (btn) window.openConcModal(btn.dataset.id);
    if (delBtn) window.deleteConcession(delBtn.dataset.id);
});

window.openConcModal = (id) => {
    const s = students.find(st=>st.id===id); if(!s) return;
    document.getElementById('conc-student-id').value = s.id;
    document.getElementById('conc-student-name').textContent = `${s.name} (Class: ${s.class || '--'}, Adm: ${s.adm || '--'})`;
    document.getElementById('conc-fee-amount').value = (s.concessionFee !== undefined && s.concessionFee !== null) ? s.concessionFee : '';
    const hasConc = s.concessionFee !== undefined && s.concessionFee !== null && s.concessionFee !== '';
    document.getElementById('conc-remove').classList.toggle('hidden', !hasConc);
    document.getElementById('concession-popup').classList.remove('hidden'); 
    document.getElementById('concession-popup').classList.add('flex');
};

document.getElementById('conc-cancel').onclick = () => document.getElementById('concession-popup').classList.add('hidden');
document.getElementById('conc-save').onclick = async () => {
    if(!requirePermission('concessions.manage')) return;
    const amt = parseFloat(document.getElementById('conc-fee-amount').value);
    if(isNaN(amt) || amt < 0) return alert("Enter valid amount");
    if(!confirm("Save this fee concession to database?")) return;
    const studentId = document.getElementById('conc-student-id').value;
    const s = students.find(st => st.id === studentId);
    if (s) {
        s.concessionFee = amt;
        s.concessionAppliedAt = Date.now();
        s.concessionUpdatedAt = Date.now();
    }
    renderConcessionsList();
    document.getElementById('concession-popup').classList.add('hidden');
    await updateDoc(doc(db, `${BASE_PATH}/students`, studentId), { concessionFee: amt, concessionAppliedAt: Date.now(), concessionUpdatedAt: Date.now() });
    await logAuditEvent({ category: 'fee', action: 'concession.save', entityType: 'student', entityId: studentId, message: `Concession saved: ₹${amt}.` });
};

document.getElementById('conc-remove').onclick = async () => {
    const studentId = document.getElementById('conc-student-id').value;
    await window.deleteConcession(studentId);
    document.getElementById('concession-popup').classList.add('hidden');
};

window.deleteConcession = async (studentId) => {
    if(!requirePermission('concessions.manage')) return;
    if(!confirm("Remove fee concession for this student?")) return;
    const s = students.find(st => st.id === studentId);
    if (s) {
        s.concessionFee = null;
        s.concessionUpdatedAt = Date.now();
    }
    renderConcessionsList();
    await updateDoc(doc(db, `${BASE_PATH}/students`, studentId), { concessionFee: null, concessionUpdatedAt: Date.now() });
    await logAuditEvent({ category: 'fee', action: 'concession.remove', entityType: 'student', entityId: studentId, message: 'Concession removed.' });
};

// --- Student Profile Dossier Helpers & Controllers ---
const buildStudent360YearModels = (student) => {
    const activeLabel = getActiveAcademicYearLabel();
    const isAlumStudent = normalizeStudentStatus(student.status) === 'Alumni'
        || student.isAlumni === true
        || String(student.class || '').toUpperCase() === 'ALUMNI';

    const historyMap = (student.academicYears && typeof student.academicYears === 'object')
        ? JSON.parse(JSON.stringify(student.academicYears))
        : {};

    if (!isAlumStudent && student.academicYear) {
        const masterYr = sanitizeAcademicYearLabel(student.academicYear) || student.academicYear;
        if (masterYr && !historyMap[masterYr]) {
            historyMap[masterYr] = {
                class: student.class || '--',
                status: student.status || 'Active',
                decision: 'Active Enrollment',
                updatedAt: student.updatedAt || null
            };
        }
    }

    const gradYrRaw = student.passedOutYear || student.graduatedYear || '';
    const gradYr = sanitizeAcademicYearLabel(gradYrRaw) || gradYrRaw;
    if (gradYr && !historyMap[gradYr]) {
        historyMap[gradYr] = {
            class: student.completedClass || student.finalClass || student.promotedFrom || student.class || '--',
            status: 'Alumni',
            decision: 'graduated',
            updatedAt: student.promotedAt || null
        };
    }

    let recordedYears = Object.keys(historyMap);
    if (!recordedYears.length) {
        const fallbackYr = sanitizeAcademicYearLabel(student.academicYear || activeLabel) || activeLabel;
        historyMap[fallbackYr] = {
            class: isAlumStudent ? (student.completedClass || student.promotedFrom || 'Alumni') : (student.class || '--'),
            status: student.status || 'Active',
            decision: isAlumStudent ? 'graduated' : 'Active Enrollment',
            updatedAt: student.updatedAt || null
        };
        recordedYears = [fallbackYr];
    }

    recordedYears.sort((a, b) => compareAcademicYearLabels(b, a) || String(b).localeCompare(String(a), undefined, { numeric: true }));

    let defaultExpandedYear = recordedYears[0];
    if (isAlumStudent) {
        if (gradYr && recordedYears.includes(gradYr)) defaultExpandedYear = gradYr;
        else if (recordedYears.includes(activeLabel)) defaultExpandedYear = activeLabel;
    } else {
        if (recordedYears.includes(activeLabel)) defaultExpandedYear = activeLabel;
        else if (student.academicYear && recordedYears.includes(student.academicYear)) defaultExpandedYear = student.academicYear;
    }

    return recordedYears.map((yr) => {
        const entry = historyMap[yr] || {};
        const rawEntryClass = entry?.class && entry.class !== '--' && String(entry.class).toUpperCase() !== 'ALUMNI'
            ? entry.class
            : '';
        const yearClass = rawEntryClass
            || (isAlumStudent && yr === defaultExpandedYear ? (student.completedClass || student.promotedFrom || student.finalClass || '') : '')
            || (yr === (student.academicYear || activeLabel) ? (student.class || '') : '');
        const isCurrent = yr === activeLabel;
        const isExpanded = yr === defaultExpandedYear;
        return {
            year: yr,
            entry,
            isCurrent,
            isExpanded,
            isAlumStudent,
            displayClass: yearClass || entry.class || '--'
        };
    });
};

const renderStu360AccordionShell = ({ year, isExpanded, isCurrent, badgeText, headerSubHtml, rightSummaryHtml, bodyHtml }) => {
    const yearPill = isCurrent
        ? `<span class="px-2 py-0.5 rounded text-[10px] font-black bg-indigo-600 text-white">Current</span>`
        : `<span class="px-2 py-0.5 rounded text-[10px] font-bold bg-slate-200/80 text-slate-700">${escapeHtml(badgeText || 'Past')}</span>`;
    return `
        <div class="stu360-year-card rounded-xl border ${isCurrent ? 'border-indigo-200' : 'border-slate-200'} bg-white overflow-hidden">
            <button type="button" class="stu360-year-toggle w-full text-left px-3.5 py-3 flex items-center justify-between flex-wrap gap-2 ${isCurrent ? 'bg-indigo-50/60 hover:bg-indigo-50' : 'bg-slate-50/80 hover:bg-slate-100/80'} transition cursor-pointer" aria-expanded="${isExpanded ? 'true' : 'false'}">
                <div class="flex items-center gap-2 flex-wrap">
                    <i class="fas fa-chevron-down text-xs text-slate-500 transition-transform duration-200 ${isExpanded ? 'rotate-180' : ''} stu360-year-chevron shrink-0"></i>
                    <span class="text-xs font-black text-slate-900 font-mono tabular-nums">${escapeHtml(year)}</span>
                    ${yearPill}
                    ${headerSubHtml || ''}
                </div>
                ${rightSummaryHtml ? `<div class="flex items-center gap-2 flex-wrap text-[11px] font-semibold">${rightSummaryHtml}</div>` : ''}
            </button>
            <div class="stu360-year-body border-t border-slate-200 p-3.5 sm:p-4 space-y-3.5 ${isExpanded ? '' : 'hidden'}">
                ${bodyHtml}
            </div>
        </div>
    `;
};

const renderStudent360AcademicHistory = (student) => {
    const timelineContainer = document.getElementById('stu360-timeline-container');
    if (!timelineContainer) return;

    const yearModels = buildStudent360YearModels(student);
    timelineContainer.innerHTML = yearModels.map((model) => {
        const { year, entry, isCurrent, isExpanded, displayClass } = model;
        const entryStatus = normalizeStudentStatus(entry.status || 'Active');
        const formattedDate = entry.updatedAt ? new Date(entry.updatedAt).toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' }) : 'Recorded';
        const decision = String(entry.decision || 'Enrolled').toLowerCase();
        let decisionBadge = `<span class="px-2 py-0.5 rounded text-[10px] font-bold bg-slate-100 text-slate-700">${escapeHtml(decision.toUpperCase())}</span>`;
        if (decision.includes('promot')) {
            decisionBadge = `<span class="px-2 py-0.5 rounded text-[10px] font-bold bg-emerald-100 text-emerald-800 border border-emerald-200"><i class="fas fa-arrow-up mr-1"></i>PROMOTED</span>`;
        } else if (decision.includes('graduat') || decision === 'alumni') {
            decisionBadge = `<span class="px-2 py-0.5 rounded text-[10px] font-bold bg-purple-100 text-purple-800 border border-purple-200"><i class="fas fa-graduation-cap mr-1"></i>ALUMNI</span>`;
        } else if (decision.includes('retain')) {
            decisionBadge = `<span class="px-2 py-0.5 rounded text-[10px] font-bold bg-amber-100 text-amber-800 border border-amber-200"><i class="fas fa-repeat mr-1"></i>RETAINED</span>`;
        }

        const phaseLabel = isCurrent ? 'Current' : (isUpcomingAcademicYearLabel(year, getActiveAcademicYearLabel()) ? 'Upcoming' : 'Past');
        const classDisplayText = displayClass && displayClass !== '--' && String(displayClass).toUpperCase() !== 'ALUMNI'
            ? `Class ${displayClass}`
            : (displayClass || '--');
        const headerSubHtml = `
            <span class="text-xs font-bold text-slate-700">• ${escapeHtml(classDisplayText)}</span>
            ${decisionBadge}
        `;

        const bodyHtml = `
            <div class="grid grid-cols-2 sm:grid-cols-4 gap-2.5 p-3 rounded-lg bg-slate-50 border border-slate-200 text-xs">
                <div>
                    <span class="text-slate-500 block text-[10px] font-bold uppercase">Enrolled Class</span>
                    <span class="font-extrabold text-slate-900">${escapeHtml(displayClass || '--')}</span>
                </div>
                <div>
                    <span class="text-slate-500 block text-[10px] font-bold uppercase">Session Status</span>
                    <span class="font-bold text-slate-800">${escapeHtml(entryStatus)}</span>
                </div>
                <div>
                    <span class="text-slate-500 block text-[10px] font-bold uppercase">Promotion / Decision</span>
                    <div class="mt-0.5">${decisionBadge}</div>
                </div>
                <div>
                    <span class="text-slate-500 block text-[10px] font-bold uppercase">Updated</span>
                    <span class="font-medium text-slate-600">${escapeHtml(formattedDate)}</span>
                </div>
            </div>
        `;

        return renderStu360AccordionShell({
            year,
            isExpanded,
            isCurrent,
            badgeText: phaseLabel,
            headerSubHtml,
            rightSummaryHtml: '',
            bodyHtml
        });
    }).join('');
};

// --- Student Full Profile Details Modal Controller ---
const openStudentDetailsModal = (studentId) => {
    const student = (rawStudents || []).find((st) => st.id === studentId) || (students || []).find((st) => st.id === studentId);
    if (!student) return;

    const modal = document.getElementById('student-full-details-modal');
    if (!modal) return;

    // Reset tabs to Bio & KYC active
    document.querySelectorAll('.stu360-tab-btn').forEach((b) => {
        b.classList.remove('active', 'border-indigo-600', 'text-indigo-700');
        b.classList.add('border-transparent', 'text-slate-500');
    });
    const firstTab = document.querySelector('.stu360-tab-btn[data-stu-pane="stu360-pane-bio"]');
    if (firstTab) {
        firstTab.classList.add('active', 'border-indigo-600', 'text-indigo-700');
        firstTab.classList.remove('border-transparent', 'text-slate-500');
    }
    document.querySelectorAll('.stu360-pane').forEach((p) => {
        if (p.id === 'stu360-pane-bio') p.classList.remove('hidden');
        else p.classList.add('hidden');
    });

    // Populate Year-Wise Academic & Promotions Timeline
    renderStudent360AcademicHistory(student);

    // Photo & Initials fallback
    const photoImg = document.getElementById('view-stu-photo');
    const photoPlaceholder = document.getElementById('view-stu-photo-placeholder');
    const photoInitials = document.getElementById('view-stu-photo-initials');
    const modalDownloadBtn = document.getElementById('modal-download-stu-photo-btn');
    const photoUrl = resolveSafePhotoUrl(student.photo || student.profilePhoto || student.photoUrl || student.profile?.photo || '');
    if (photoInitials) photoInitials.textContent = getStudentInitials(student.name);
    if (photoImg && photoPlaceholder) {
        photoImg.onerror = null;
        if (photoUrl) {
            photoImg.onerror = () => {
                photoImg.onerror = null;
                photoImg.classList.add('hidden');
                photoPlaceholder.classList.remove('hidden');
                if (modalDownloadBtn) {
                    modalDownloadBtn.classList.add('hidden');
                    modalDownloadBtn.onclick = null;
                }
            };
            photoImg.src = photoUrl;
            photoImg.classList.remove('hidden');
            photoPlaceholder.classList.add('hidden');
            if (modalDownloadBtn) {
                modalDownloadBtn.classList.remove('hidden');
                modalDownloadBtn.onclick = () => downloadStudentPhotoAsPng(photoUrl, student.name);
            }
        } else {
            photoImg.removeAttribute('src');
            photoImg.classList.add('hidden');
            photoPlaceholder.classList.remove('hidden');
            if (modalDownloadBtn) {
                modalDownloadBtn.classList.add('hidden');
                modalDownloadBtn.onclick = null;
            }
        }
    }

    const setText = (id, val) => {
        const el = document.getElementById(id);
        if (el) el.textContent = val || '--';
    };

    const statusVal = normalizeStudentStatus(student.status || student.profile?.status || 'Active');
    const isAlumniRecord = statusVal === 'Alumni' || student.isAlumni === true || String(student.class || '').toUpperCase() === 'ALUMNI';
    const batchYearVal = student.passedOutYear || student.graduatedYear || '';
    const completedClassVal = student.completedClass || student.promotedFrom || '';
    const displayClass = isAlumniRecord ? (completedClassVal || 'Alumni') : (student.class || 'No Class');

    setText('view-stu-name', student.name || 'Unnamed Student');
    setText('view-stu-adm', student.adm || '--');
    setText('view-stu-uid', student.uid || student.id || '--');

    const classBadge = document.getElementById('view-stu-class-badge');
    if (classBadge) {
        classBadge.textContent = isAlumniRecord
            ? (completedClassVal ? `Alumni · ${completedClassVal}` : 'Alumni Archive')
            : (student.class ? `Class ${student.class}` : 'No Class');
    }

    const statusBadge = document.getElementById('view-stu-status-badge');
    if (statusBadge) {
        statusBadge.textContent = statusVal;
        statusBadge.className = statusVal === 'Active'
            ? 'font-bold text-emerald-300'
            : (statusVal === 'Alumni' ? 'font-bold text-purple-300' : 'font-bold text-rose-300');
    }

    const genderBadge = document.getElementById('view-stu-gender-badge');
    if (genderBadge) genderBadge.textContent = student.gender || 'Not Specified';

    // Alumni Archive Section
    const alumniSection = document.getElementById('view-stu-alumni-section');
    if (alumniSection) {
        if (isAlumniRecord) {
            alumniSection.classList.remove('hidden');
            setText('view-stu-batch-val', batchYearVal ? `Batch ${batchYearVal}` : '--');
            setText('view-stu-completed-class-val', completedClassVal || student.class || '--');
        } else {
            alumniSection.classList.add('hidden');
        }
    }

    // Academic & Personal
    const academicYrVal = isAlumniRecord
        ? (batchYearVal || student.academicYear || activeAcademicYear || currentAcademicYear || '--')
        : (student.academicYear || activeAcademicYear || currentAcademicYear || '--');
    const dobRaw = student.dob || student.profile?.dob || '';
    const admDateRaw = student.admDate || student.profile?.admDate || '';
    const adhaarRaw = student.adhaar || student.aadhaar || student.profile?.adhaar || student.profile?.aadhaar || '';

    setText('view-stu-academic-year', academicYrVal);
    setText('view-stu-academic-year-val', academicYrVal);
    setText('view-stu-adm-val', student.adm || '--');
    setText('view-stu-class-val', isAlumniRecord ? (completedClassVal || 'Alumni') : (student.class ? `Class ${student.class}` : '--'));
    setText('view-stu-uid-val', student.uid || student.id || '--');
    setText('view-stu-gender-val', student.gender || '--');
    setText('view-stu-dob-val', dobRaw ? (dobRaw.includes('-') && dobRaw.split('-').length === 3 ? `${dobRaw.split('-')[2]}/${dobRaw.split('-')[1]}/${dobRaw.split('-')[0]}` : dobRaw) : '--');
    setText('view-stu-adm-date-val', admDateRaw ? (admDateRaw.includes('-') && admDateRaw.split('-').length === 3 ? `${admDateRaw.split('-')[2]}/${admDateRaw.split('-')[1]}/${admDateRaw.split('-')[0]}` : admDateRaw) : '--');
    setText('view-stu-status-val', statusVal);
    setText('view-stu-adhaar-val', adhaarRaw || '--');

    // Parents & Contact
    const fatherName = student.father || student.fatherName || student.profile?.father || '';
    const fatherPhone = student.mobile || student.fatherMobile || student.parentPhone || student.phone || student.profile?.fatherMobile || '';
    const motherName = student.mother || student.motherName || student.profile?.mother || '';
    const motherPhone = student.motherMobile || student.profile?.motherMobile || '';
    const address = student.address || student.permanentAddress || student.profile?.address || '';

    setText('view-stu-father-name', fatherName || 'Not recorded');
    setText('view-stu-father-phone', fatherPhone || 'Not recorded');
    setText('view-stu-mother-name', motherName || 'Not recorded');
    setText('view-stu-mother-phone', motherPhone || 'Not recorded');
    setText('view-stu-address-val', address || 'No address provided');

    // Sync visibility & labels with configured studentFieldSchema
    modal.querySelectorAll('[data-stu-detail-field]').forEach((wrap) => {
        const fKey = wrap.getAttribute('data-stu-detail-field');
        const fieldDef = getStudentFieldByKey(studentFieldSchema, fKey);
        if (!fieldDef) return;
        wrap.classList.toggle('hidden', !fieldDef.visible);
        const lblEl = wrap.querySelector(`[data-stu-detail-label="${fKey}"]`);
        if (lblEl) lblEl.textContent = fieldDef.label;
    });

    // Render visible custom fields in configured order
    const customSection = document.getElementById('view-stu-custom-fields-section');
    const customGrid = document.getElementById('view-stu-custom-fields-grid');
    if (customSection && customGrid) {
        const visibleCustom = getCustomStudentFields(studentFieldSchema, { onlyVisible: true });
        if (visibleCustom.length > 0) {
            customSection.classList.remove('hidden');
            customGrid.innerHTML = visibleCustom.map((cf) => {
                const displayVal = formatStudentFieldDisplayValue(student, cf, '--');
                const loginBadge = cf.type === 'phone'
                    ? ' <span class="inline-flex items-center px-1.5 py-0.2 rounded bg-emerald-50 text-emerald-700 border border-emerald-200 text-[9px] font-bold ml-1">Login</span>'
                    : '';
                const isWide = cf.type === 'textarea';
                return `
                    <div class="${isWide ? 'col-span-2 sm:col-span-3' : ''}">
                        <span class="block text-[11px] font-medium text-slate-500">${escapeHtml(cf.label)}${loginBadge}</span>
                        <span class="font-semibold text-slate-900 text-sm mt-0.5 block ${cf.type === 'phone' || cf.type === 'number' || cf.type === 'date' ? 'font-mono tabular-nums' : ''} break-words whitespace-pre-wrap">${escapeHtml(displayVal)}</span>
                    </div>
                `;
            }).join('');
        } else {
            customSection.classList.add('hidden');
            customGrid.innerHTML = '';
        }
    }

    // Concession Info
    const concVal = document.getElementById('view-stu-concession-val');
    const concAmt = document.getElementById('view-stu-concession-amt');
    if (student.concessionFee !== undefined && student.concessionFee !== null && student.concessionFee !== '') {
        if (concVal) concVal.textContent = 'Special Fee Applied';
        if (concAmt) {
            concAmt.textContent = `${formatCurrency(student.concessionFee)}/month`;
            concAmt.classList.remove('hidden');
        }
    } else {
        if (concVal) concVal.textContent = 'None (Standard Fee Applies)';
        if (concAmt) concAmt.classList.add('hidden');
    }

    // Group Info
    const groupVal = document.getElementById('view-stu-group-val');
    const groupAmt = document.getElementById('view-stu-group-amt');
    const linkedGroup = (studentGroups || []).find((g) => Array.isArray(g.memberIds) && g.memberIds.includes(student.id));
    if (linkedGroup) {
        if (groupVal) groupVal.textContent = `Linked to Group (${(linkedGroup.memberIds || []).length} members)`;
        if (groupAmt) {
            groupAmt.textContent = `${formatCurrency(linkedGroup.fee || 0)}/month`;
            groupAmt.classList.remove('hidden');
        }
    } else {
        if (groupVal) groupVal.textContent = 'Not in a student group';
        if (groupAmt) groupAmt.classList.add('hidden');
    }

    modal.classList.remove('hidden');
    modal.classList.add('flex');
};

