// --- AUTH & FIREBASE INIT ---
onAuthStateChanged(auth, async (user) => {
    if (!user) {
        window.location.replace(getPageUrl('index.html'));
        return;
    }
    const requestedTab = (window.location.hash || '#dashboard').replace('#', '') || 'dashboard';
    if (requestedTab === 'results') {
        window.location.replace(`${getPageUrl('result.html')}?from=admin`);
        return;
    }
    const tenantCheck = await ensureTenantStatusAndAccess({
        db,
        requiredPage: 'admin',
        institutionId: INSTITUTION_ID,
        liveWatch: true,
        onStatusUpdate: () => {
            syncCompanyLockedAdminControls();
            renderDashboard();
            if (!document.getElementById('workflow-modules-page')?.classList.contains('hidden')) {
                renderWorkflowModules();
            }
        }
    });
    syncCompanyLockedAdminControls();
    onPlanChange(() => {
        syncCompanyLockedAdminControls();
        renderDashboard();
    });
    if (!tenantCheck?.active) {
        const loader = document.getElementById('auth-loader');
        if (loader) loader.style.display = 'none';
        return;
    }
    window.AppSession?.touchSession();

    try {
        const claims = await getAuthClaims(user);
        currentAdminClaims = claims;
        const normalizedInstId = String(INSTITUTION_ID || '').trim().toLowerCase();
        const adminRef = getAdminAuthRef();
        const snap = await getDoc(adminRef);
        const adminDocData = snap.exists() ? (snap.data() || {}) : {};

        let companyOwnerAuthorized = false;
        if (!claims.customAuth && user.email) {
            try {
                const companySnap = await getDoc(doc(db, 'company', 'config'));
                const ownerEmails = Array.isArray(companySnap.data()?.ownerEmails)
                    ? companySnap.data().ownerEmails.map((e) => String(e || '').trim().toLowerCase())
                    : [];
                const ownerEmailSingle = String(companySnap.data()?.ownerEmail || '').trim().toLowerCase();
                const userEmailNorm = normalizeEmail(user.email);
                companyOwnerAuthorized = Boolean(
                    userEmailNorm && (ownerEmails.includes(userEmailNorm) || (ownerEmailSingle && ownerEmailSingle === userEmailNorm))
                );
            } catch (_) {}
        }

        const isCustomSuperAdmin = Boolean(
            claims.customAuth
            && claims.role === 'super_admin'
            && claims.institutionId === normalizedInstId
            && snap.exists()
            && adminDocData.isActive !== false
            && (!adminDocData.uid || adminDocData.uid === user.uid)
        );

        let authorizedStaffAdmin = null;
        if (!isCustomSuperAdmin && !companyOwnerAuthorized && claims.customAuth && claims.role === 'staff' && claims.institutionId === normalizedInstId) {
            try {
                const accessSnap = await getDoc(doc(db, STAFF_ACCESS_COLLECTION, user.uid));
                const accessData = accessSnap.exists() ? (accessSnap.data() || {}) : null;
                if (accessData && accessData.isActive !== false && (accessData.canAccessAdmin === true || accessData.actLikeSuperAdmin === true)) {
                    let staffFull = {};
                    const targetStaffId = claims.staffId || accessData.staffId || '';
                    if (targetStaffId) {
                        const sSnap = await getDoc(doc(db, `${BASE_PATH}/staff`, targetStaffId)).catch(() => null);
                        if (sSnap?.exists()) staffFull = sSnap.data() || {};
                    }
                    authorizedStaffAdmin = {
                        ...staffFull,
                        ...accessData,
                        id: targetStaffId || accessData.staffId || ''
                    };
                }
            } catch (staffAuthErr) {
                console.warn('Staff admin access check warning:', staffAuthErr);
            }
        }

        isCompanyOwnerSession = companyOwnerAuthorized;
        isStaffAdminSession = Boolean(authorizedStaffAdmin);
        staffAdminRecord = authorizedStaffAdmin;

        if (isCustomSuperAdmin || companyOwnerAuthorized) {
            currentAdminEmail = claims.displayUsername || claims.username || normalizeEmail(user.email || adminDocData.displayUsername || adminDocData.username || '');
            currentAdminRole = 'super_admin';
            window.AppSession?.startAdmin();
        } else if (authorizedStaffAdmin) {
            currentAdminEmail = claims.displayUsername || claims.username || authorizedStaffAdmin.displayUsername || authorizedStaffAdmin.username || '';
            currentAdminRole = (authorizedStaffAdmin.actLikeSuperAdmin === true || authorizedStaffAdmin.canAccessAdmin === true) ? 'super_admin' : 'operations_admin';
            window.AppSession?.startStaff(authorizedStaffAdmin.name || claims.displayUsername || 'Staff Admin', currentAdminEmail, {
                ...(window.AppSession?.getStaffAccess?.() || {}),
                uid: user.uid,
                username: claims.username || authorizedStaffAdmin.username || '',
                displayUsername: claims.displayUsername || authorizedStaffAdmin.displayUsername || currentAdminEmail,
                loginId: claims.displayUsername || currentAdminEmail,
                userKey: claims.username || currentAdminEmail,
                collection: authorizedStaffAdmin.canCollect === true,
                result: authorizedStaffAdmin.canManageResults === true,
                worksheet: authorizedStaffAdmin.canAccessWorksheet === true,
                attendance: authorizedStaffAdmin.canAccessAttendance === true,
                academicPlan: authorizedStaffAdmin.canAccessAcademicPlan === true,
                studentActivity: authorizedStaffAdmin.canAccessActivity === true,
                classroomEvaluation: authorizedStaffAdmin.canAccessEvaluation === true,
                evaluation: authorizedStaffAdmin.canAccessEvaluation === true,
                canAccessEvaluation: authorizedStaffAdmin.canAccessEvaluation === true,
                admin: true,
                canAccessAdmin: true,
                actLikeSuperAdmin: authorizedStaffAdmin.actLikeSuperAdmin === true || authorizedStaffAdmin.canAccessAdmin === true,
                staffId: authorizedStaffAdmin.id || claims.staffId || '',
                role: authorizedStaffAdmin.role || authorizedStaffAdmin.type || 'Staff',
                type: authorizedStaffAdmin.type || 'Staff',
                phone: authorizedStaffAdmin.phone || '',
                photo: authorizedStaffAdmin.photo || ''
            });
        } else {
            alert("Unauthorized access! You do not have permission to view this page.");
            await window.AppSession?.clearAll({ purgeClientData: true });
            await signOut(auth);
            window.location.href = getPageUrl('index.html');
            return;
        }

        const primaryDisplayId = adminDocData.displayUsername || adminDocData.username || adminDocData.email || currentAdminEmail;
        adminAccounts = [{
            name: adminDocData.name || 'Master Admin',
            email: primaryDisplayId,
            phone: adminDocData.phone || adminDocData.phoneE164 || '',
            role: 'super_admin',
            isActive: adminDocData.isActive !== false,
            createdAt: adminDocData.createdAt || new Date().toISOString(),
            updatedAt: adminDocData.updatedAt || new Date().toISOString()
        }];

        document.getElementById('auth-loader').style.display = 'none';
        document.getElementById('admin-app').style.display = 'block';
        applyRoleAccessUI();
        ensureActiveAdminPageAccess();
        enforceResultOperatorModeUI();
        renderSessionMonitor();

        const configRef = doc(db, `${BASE_PATH}/settings`, 'config');
        const academicYearsRef = doc(db, `${BASE_PATH}/settings`, 'academicYears');
        const sessionControlRef = doc(db, `${BASE_PATH}/settings`, 'sessionControl');
        const sessionRegistryRef = getSessionRegistryRef();

        onSnapshot(adminRef, (adminSnap) => {
            const adminData = adminSnap.exists() ? adminSnap.data() : {};
            const liveDisplayId = adminData.displayUsername || adminData.username || adminData.email || currentAdminEmail;
            adminAccounts = [{
                name: adminData.name || 'Master Admin',
                email: liveDisplayId,
                phone: adminData.phone || adminData.phoneE164 || '',
                role: 'super_admin',
                isActive: adminData.isActive !== false,
                createdAt: adminData.createdAt || new Date().toISOString(),
                updatedAt: adminData.updatedAt || new Date().toISOString()
            }];

            if (isCompanyOwnerSession || isStaffAdminSession) {
                applyRoleAccessUI();
                ensureActiveAdminPageAccess();
                renderAdminRoleList();
                renderDashboard();
                startSessionRegistryHeartbeat();
                return;
            }

            const stillActiveSuperAdmin = Boolean(
                adminSnap.exists()
                && adminData.isActive !== false
                && (!adminData.uid || adminData.uid === user.uid)
            );
            if (!stillActiveSuperAdmin) {
                if (adminSnap.metadata?.fromCache) return;
                window.AppSession?.revokeCurrentAccount?.({
                    accountId: 'admin_master',
                    message: 'Your admin access was removed or disabled. Please sign in again.',
                    authInstance: auth,
                    redirectUrl: getPageUrl('index.html')
                });
                return;
            }

            currentAdminRole = 'super_admin';
            applyRoleAccessUI();
            ensureActiveAdminPageAccess();
            renderAdminRoleList();
            renderDashboard();
            startSessionRegistryHeartbeat();
        });

        if (isStaffAdminSession && staffAdminRecord?.id) {
            onSnapshot(doc(db, `${BASE_PATH}/staff`, staffAdminRecord.id), (staffDocSnap) => {
                const sData = staffDocSnap.exists() ? staffDocSnap.data() : null;
                if (!sData || sData.isActive === false || sData.canAccessAdmin !== true) {
                    if (staffDocSnap.metadata?.fromCache) return;
                    window.AppSession?.revokeCurrentAccount?.({
                        accountId: staffAdminRecord.id,
                        message: 'Your staff admin access was removed or disabled. Please sign in again.',
                        authInstance: auth,
                        redirectUrl: getPageUrl('index.html')
                    });
                    return;
                }
                currentAdminRole = (sData.actLikeSuperAdmin === true || sData.canAccessAdmin === true) ? 'super_admin' : 'operations_admin';
                applyRoleAccessUI();
                ensureActiveAdminPageAccess();
            });
        }
        onSnapshot(sessionControlRef, (sessionSnap) => {
            sessionControl = sessionSnap.exists() ? sessionSnap.data() : {};
            renderSessionMonitor();
            const startedAt = window.AppSession?.getStartedAt?.() || 0;
            const forcedAt = sessionControl?.lastForcedLogoutAt ? new Date(sessionControl.lastForcedLogoutAt).getTime() : 0;
            if (forcedAt && startedAt && forcedAt > startedAt) {
                alert(sessionControl.message || 'An administrator ended this session. Please sign in again.');
                window.logoutAdmin();
            }
        });
        getDoc(sessionRegistryRef).then((sessionRegistrySnap) => {
            sessionRegistry = sessionRegistrySnap.exists() ? sessionRegistrySnap.data() : { sessions: {} };
            renderSessionMonitor();
        });
        const auditLogsQuery = query(
            collection(db, `${BASE_PATH}/auditLogs`),
            orderBy('createdAt', 'desc'),
            limit(50)
        );
        onSnapshot(auditLogsQuery, (auditSnap) => {
            auditLogs = auditSnap.docs.map((d) => ({ id: d.id, ...d.data() }));
            renderAuditLogList();
            renderDashboard();
            renderBackupCategoryCounts();
        }, (err) => {
            console.warn('Audit logs stream error, falling back to unconstrained query:', err);
            onSnapshot(collection(db, `${BASE_PATH}/auditLogs`), (fallbackSnap) => {
                auditLogs = fallbackSnap.docs.map((d) => ({ id: d.id, ...d.data() }))
                    .sort((a, b) => new Date(b.createdAt || 0) - new Date(a.createdAt || 0))
                    .slice(0, 50);
                renderAuditLogList();
                renderDashboard();
                renderBackupCategoryCounts();
            });
        });

        onSnapshot(academicYearsRef, async (academicSnap) => {
            if (!academicSnap.exists()) {
                academicYears = [{
                    label: currentAcademicYear,
                    startYear: parseInt(currentAcademicYear.split('-')[0], 10),
                    endYear: parseInt(currentAcademicYear.split('-')[1], 10),
                    startMonth: 5,
                    endMonth: 4,
                    status: 'active',
                    classes: getDefaultClassLadder()
                }];
                activeAcademicYear = currentAcademicYear;
                await persistAcademicYears();
                renderAcademicYears();
                refreshAcademicYearScopedData();
                renderBackupCategoryCounts();
                return;
            }

            const data = academicSnap.data();
            academicYears = Array.isArray(data.years) && data.years.length ? data.years : [{
                label: currentAcademicYear,
                startYear: parseInt(currentAcademicYear.split('-')[0], 10),
                endYear: parseInt(currentAcademicYear.split('-')[1], 10),
                startMonth: 5,
                endMonth: 4,
                status: 'active',
                classes: getDefaultClassLadder()
            }];
            academicYears = academicYears.map((year) => ({
                ...year,
                label: sanitizeAcademicYearLabel(year.label || `${year.startYear}-${year.endYear}`),
                startMonth: Number.isFinite(Number(year.startMonth)) ? Number(year.startMonth) : 5,
                endMonth: Number.isFinite(Number(year.endMonth)) ? Number(year.endMonth) : 4,
                classes: (() => {
                    const normalized = sortClassLabels(Array.isArray(year.classes) ? year.classes.map((name) => name?.toString().trim().toUpperCase()).filter(Boolean) : []);
                    return normalized.length ? normalized : getDefaultClassLadder();
                })()
            }));
            const resolvedCurrent = resolveAuthoritativeCurrentYear(data, currentAcademicYear);
            const prevActive = activeAcademicYear;
            activeAcademicYear = sanitizeAcademicYearLabel(resolvedCurrent || academicYears.find((year) => year.status === 'active')?.label || currentAcademicYear);
            currentAcademicYear = activeAcademicYear;
            syncCurrentYearToStorage(activeAcademicYear);
            const shouldForceCurrent = !hasLoadedAcademicYearsSnapshot || (prevActive && prevActive !== activeAcademicYear);
            hasLoadedAcademicYearsSnapshot = true;

            populateAcademicYearPresetSelector();
            const yearInput = document.getElementById('academic-year-input');
            const statusSelect = document.getElementById('academic-year-status');
            const startMonthSelect = document.getElementById('academic-year-start-month');
            const endMonthSelect = document.getElementById('academic-year-end-month');
            const activeYearRecord = academicYears.find((year) => year.label === activeAcademicYear) || {};
            if (statusSelect) statusSelect.value = activeYearRecord.status || 'active';
            if (startMonthSelect) startMonthSelect.value = String(activeYearRecord.startMonth ?? 5);
            if (endMonthSelect) endMonthSelect.value = String(activeYearRecord.endMonth ?? 4);
            renderAcademicYears();
            refreshAcademicYearScopedData(shouldForceCurrent);
            renderBackupCategoryCounts();
            if (shouldForceCurrent) {
                scheduleAutoStatsSync(300);
            }
        });

        onSnapshot(configRef, (docSnap) => {
            const d = docSnap.exists() ? docSnap.data() : {};
            latestConfigData = { ...d };
            latestPublishedStats = normalizeInstitutionalStats(d.stats || {});
            hasLoadedConfigSnapshot = true;
            if (latestPublishedStats.hasStats) {
                updateStatsSyncBadge('synced', latestPublishedStats.updatedAt);
            } else {
                updateStatsSyncBadge('ready');
            }

            // --- AUTO GENERATE 12 MONTHS FOR ACADEMIC YEARS ---
            let existingItems = Array.isArray(d.feeItems) ? [...d.feeItems] : [];
            let isUpdated = false;
            const targetYears = (Array.isArray(academicYears) && academicYears.length)
                ? academicYears
                : (getActiveAcademicYearRecord() ? [getActiveAcademicYearRecord()] : []);

            targetYears.forEach((yearRecord) => {
                if (!yearRecord || !yearRecord.label || yearRecord.status === 'archived') return;
                const yearLabel = yearRecord.label;
                const suffix = yearLabel.replace(/[^0-9]/g, '').substring(2);
                const months = getAcademicMonthSequence(yearRecord).map((monthIndex) => MONTH_LABELS[monthIndex]);

                months.forEach((m) => {
                    const key = `${m.toLowerCase().substring(0, 3)}-${suffix}`;
                    if (!existingItems.find((i) => i.key === key)) {
                        existingItems.push({
                            key: key,
                            name: `${m} (${yearLabel})`,
                            type: 'month',
                            isVisible: true,
                            academicYear: yearLabel
                        });
                        isUpdated = true;
                    }
                });
            });

            if (isUpdated) {
                setDoc(configRef, { feeItems: existingItems, appName: d.appName || 'Institution Manage', defaultFee: d.defaultFee || 200 }, { merge: true });
            }

            const appNameHeaderEl = document.getElementById('app-name-header');
            if (appNameHeaderEl) appNameHeaderEl.textContent = d.appName || 'Admin Dashboard';
            const footerInstEl = document.getElementById('footer-inst-name');
            if (footerInstEl) footerInstEl.textContent = d.appName || 'Institution Name';
            renderVersionInfo();
            const appSubtitleHeaderEl = document.getElementById('app-subtitle-header');
            if (appSubtitleHeaderEl) appSubtitleHeaderEl.textContent = d.appSubtitle || 'Institute Management';
            const effectiveLogoUrl = rememberInstitutionLogo(d.logoUrl || '', d.appName || '') || '/assets/images/logo.png';
            ['admin-header-logo', 'admin-loader-logo'].forEach((id) => {
                const logoEl = document.getElementById(id);
                if (!logoEl) return;
                logoEl.src = effectiveLogoUrl;
                logoEl.onerror = () => {
                    logoEl.onerror = null;
                    logoEl.src = '/assets/images/logo.png';
                };
            });

            const setValueIfExists = (id, value = '') => {
                const element = document.getElementById(id);
                if (element) element.value = value;
            };
            populateBasicInfoForm(d, { preservePendingLogo: Boolean(pendingUnsavedLogoUrl) });
            setValueIfExists('default-fee-input', d.defaultFee || 200);
            setValueIfExists('fee-status-title-input', d.feeStatusTitle || '');
            const defaultReceiptReqEl = document.getElementById('default-fee-receipt-req');
            if (defaultReceiptReqEl) defaultReceiptReqEl.checked = d.defaultReceiptMandatory || false;
            setValueIfExists('fee-collect-start-day', String(d.feeCollectionStartDay || 1));
            setValueIfExists('fee-collect-end-day', String(d.feeCollectionEndDay || 10));
            setValueIfExists('fee-notify-mode', d.feeNotifyMode || 'month_start');
            setValueIfExists('fee-notify-days-before', String(d.feeNotifyDaysBefore || 5));
            updateFeeScheduleLiveSummary();

            const photoUploadToggle = document.getElementById('admin-toggle-student-photo-upload');
            if (photoUploadToggle) photoUploadToggle.checked = d.allowStudentPhotoUpload === true;
            const detailsEditToggle = document.getElementById('admin-toggle-student-details-edit');
            if (detailsEditToggle) detailsEditToggle.checked = d.allowStudentDetailsEdit === true;

            studentFieldSchema = normalizeStudentFieldSchema(d.studentFields);
            applyStudentFieldSchemaToForm('add-student-fields-grid', 'add-stu-', studentFieldSchema, {}, 'add');

            if (d.enabledModules && typeof d.enabledModules === 'object') {
                localStorage.setItem('app_enabled_modules', JSON.stringify({ ...DEFAULT_ENABLED_MODULES, ...d.enabledModules }));
                if (!document.getElementById('workflow-modules-page')?.classList.contains('hidden')) {
                    renderWorkflowModules();
                }
            }

            feeItems = existingItems;
            renderDashboard();
            const feeSettingsPageEl = document.getElementById('fee-settings-page');
            if (feeSettingsPageEl && !feeSettingsPageEl.classList.contains('hidden')) renderFeeItemsManagement();
            renderBackupCategoryCounts();
            if (hasLoadedStudentsSnapshot) {
                scheduleAutoStatsSync(250);
            }
        });

        onSnapshot(doc(db, `${BASE_PATH}/settings`, 'content'), (snap) => {
            webContent = snap.exists() ? Object.assign({ notices: [], gallery: [], directoryCategories: [] }, snap.data()) : { notices: [], gallery: [], directoryCategories: [] };
            const aboutEl = document.getElementById('web-about');
            if (aboutEl) aboutEl.value = webContent.description || '';
            renderWebNotices(); renderWebGallery();
            renderDirectoryCategories();
            renderBackupCategoryCounts();
        });
        onSnapshot(doc(db, `${BASE_PATH}/settings`, 'categoryAuthConfig'), (snap) => {
            categoryAuthConfig = normalizeCategoryAuthConfig(snap.exists() ? snap.data() : {});
            renderDirectoryAuthConfig();
        });
        onSnapshot(doc(db, `${BASE_PATH}/settings`, 'pageAccess'), (snap) => {
            pageAccessConfig = normalizePageAccessConfig(snap.exists() ? snap.data() : {});
            renderDirectoryAccessConfig();
            renderOverrideEntryOptions();
        });
        onSnapshot(collection(db, `${BASE_PATH}/publicDirectory`), (snap) => {
            publicDirectoryEntries = snap.docs.map((d) => ({ id: d.id, ...d.data() }));
            renderDirectoryEntries();
            renderBackupCategoryCounts();
        });

        onSnapshot(collection(db, `${BASE_PATH}/students`), (snap) => {
            rawStudents = snap.docs.map(d => ({id: d.id, ...d.data()}));
            hasLoadedStudentsSnapshot = true;
            refreshAcademicYearScopedData();
            renderAcademicYears();
            renderBackupCategoryCounts();
            scheduleAutoStatsSync(250);
        });

        document.getElementById('btn-publish-stats')?.addEventListener('click', () => publishInstitutionalStats(false, { force: true }));

        document.getElementById('btn-sync-student-lookup')?.addEventListener('click', async () => {
            const btn = document.getElementById('btn-sync-student-lookup');
            if (btn) {
                btn.disabled = true;
                btn.innerHTML = '<i class="fas fa-spinner fa-spin mr-1"></i> Syncing...';
            }
            try {
                const count = await syncAllStudentsLookupIndex(rawStudents);
                showToast(`Student Login Index synchronized successfully (${count} records).`, 'success');
            } catch (err) {
                showToast('Failed to sync student login index: ' + err.message, 'error');
            } finally {
                if (btn) {
                    btn.disabled = false;
                    btn.innerHTML = '<i class="fas fa-sync-alt"></i><span>Sync Student Login Index</span>';
                }
            }
        });

        onSnapshot(collection(db, `${BASE_PATH}/staff`), (snap) => {
            allStaff = snap.docs.map(d => ({id: d.id, ...d.data()}));

            renderDashboard();
            renderAcademicYears();
            if(!document.getElementById('staff-management-page')?.classList.contains('hidden') || !document.getElementById('manage-staff-page')?.classList.contains('hidden')) renderStaffList();
            renderBackupCategoryCounts();
        });

        onSnapshot(collection(db, `${BASE_PATH}/studentGroups`), (snap) => {
            const rawGroups = snap.docs.map(d => ({id: d.id, ...d.data()}));
            allStudentGroups = rawGroups;
            populateGroupsAcademicYearDropdown();
            filterStudentGroupsForSelectedYear();
            renderDashboard();
            if(!document.getElementById('manage-groups-page').classList.contains('hidden')) renderStudentGroups();
            renderBackupCategoryCounts();
        });

        onSnapshot(collection(db, `${BASE_PATH}/payments`), (snap) => {
            allPayments = snap.docs.map(d => ({id: d.id, ...d.data()}));
            renderBackupCategoryCounts();
        });

        // Result module fully moved to standalone result.html/result-page.js.

    } catch (error) {
        console.error("Auth Error:", error);
        alert("Security verification error occurred.");
        window.location.href = getPageUrl('index.html');
    }
});
